    Text = "ทีมเดียว: หลังจากสลับท่าทางหนวดสัมผัสด้วยตนเอง, ใช้เตาหลอมเลือด, ปล่อย「ทำลายล้าง」, จะจั่วการ์ดคำสั่งของผู้สวมใส่ 1 ใบ, แต่ละผลมีคูลดาวน์ 3 รอบ. อัตราการประสานที่ผู้ปลุกตื่นทั้งหมดได้รับจากการสำรวจเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>."
