    Text = "เปลี่ยนท่าทางข้อมืออย่างกระตือรือร้น(เวลาคูลดาวน์ที่เหลืออยู่ [DescArg1] เทิร์น),      ใช้เตาหลอมสีแดง(เวลาคูลดาวน์ที่เหลืออยู่ [DescArg2] เทิร์น),      หลังจากปล่อย 「การทำลาย」(เวลาคูลดาวน์ที่เหลืออยู่ [DescArg3] เทิร์น),      ดึงการ์ดคำสั่งของผู้ติดอาวุธ 1 ใบ,      แต่ละผลกระทบมีเวลาคูลดาวน์ 3 เทิร์น. หลังจากสำเร็จการสำรวจ,      อัตราการประสานที่ได้รับจากทุกตัวที่ตื่นขึ้นจะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>.."
