  },
  State_123507_WeaponDesc = {
    Text = "เริ่มต้นการสำรวจ จะเพิ่มการ์ด 1 ใบ「เวลานับถอยหลัง: 5」ลงในกองไพ่: เมื่อเล่นจะจั่วไพ่ 1 ใบ และสับการ์ด「เวลานับถอยหลัง」ใบถัดไปลงในกองทิ้ง.「<DestructionKeywords:ทำลาย>」.「เวลานับถอยหลัง: 0」: จั่วไพ่ 3 ใบ จะได้รับ 3 หน่วยอริธเมทิกา และมีความน่าจะเป็น <WeaponEffect_Num:[StateArg1]%> ที่จะสับ「เวลานับถอยหลัง: 5」ลงในกองทิ้ง.เก็บรักษา.「<DestructionKeywords:ทำลาย>」."
