    Text = "ทีมเดียว: ความเสียหายพิษคงที่ที่สร้างโดยผู้สวมใส่และผลกระทบพิษที่กระตุ้นเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> การฟื้นฟูอัตโนมัติในดินแดนเนื้อและเลือด <EmbryoFusionIconKeywords:หลอมรวมตัวอ่อน> เพิ่มขึ้น <WeaponEffect_Num:[StateArg2] %> เมื่อผู้สวมใส่กระตุ้น「การสั่นสะเทือน」ครั้งแรกในแต่ละเทิร์น ผู้ปลุกตื่นอื่นๆ จะได้รับ <WeaponEffect_Num:[StateArg3]> คะแนนอาลีมัส."
  },
  State_126010_WeaponDesc = {
