  State_131749_Desc = {
    Text = "ทีมเดียว：หลังจากเริ่มต้นการสำรวจ จะสับไพ่ 1 ใบ「ปัญญาแห่งการพนัน」เข้ากองไพ่ที่สุ่ม.「ปัญญาแห่งการพนัน」：ใช้ 1 อริธเมทิกา.นำการ์ดคำสั่งทั้งหมดในมือแบบสุ่มสับเข้าไปในกองไพ่ที่สุ่ม การ์ดคำสั่งที่สับเข้าไปจะมีโอกาส <WeaponEffect_Num:[StateArg1]%> ที่จะมีผลเพิ่มเติม 1 ครั้งเมื่อเล่นครั้งถัดไป และทุกครั้งที่สับการ์ดคำสั่ง 1 ใบ จะทำให้ผู้ปลุกตื่นทั้งหมดได้รับ 2 จุดอาลีมัส.<RetainIconKeywords:เก็บรักษา>.<DepleteIconKeywords:ใช้>.<GuyouKeywords:ติดตัว>."
  },
  State_131749_WeaponDesc = {
    Text = "เมื่อเริ่มการสำรวจ ให้สับไพ่ 1 ใบ「ปัญญาแห่งการพนัน」เข้าไปในกองไพ่ที่สุ่ม.「ปัญญาแห่งการพนัน」：ใช้พลังการคำนวณ 1 หน่วย.สับการ์ดคำสั่งทั้งหมดในมือแบบสุ่มเข้าไปในกองไพ่ที่สุ่ม การ์ดคำสั่งที่สับเข้าไปจะมีโอกาส <WeaponEffect_Num:[StateArg1]%> ที่จะมีผลเพิ่มเติม 1 ครั้งเมื่อเล่นครั้งถัดไป และสำหรับการ์ดคำสั่งที่สับเข้าไป 1 ใบ จะทำให้ผู้ปลุกตื่นทั้งหมดได้รับ 2 คะแนนอาลีมัส.<RetainIconKeywords:เก็บรักษา>.<DepleteIconKeywords:ใช้>.<GuyouKeywords:ติดตัว>."
  },
