  State_132891_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อสวมใส่จะได้รับ [StateArg1] <StrongEffectKeywords:Amp.> หลังจากมิตรอื่นระเบิดพลังคลั่ง ทำให้พวกเขาได้รับ<PVPOneMeetingKeywords:โอกาสเดียวในชีวิต>."
  },
  State_132891_Name = {
    Text = "ปริศนาใต้ดอกซากุระ"
  },
  State_132892_Desc = {
    Text = "·เมื่อได้รับ จะลบสภาพ「อิจิโกะอิจิเอะ」ของพันธมิตรอื่น และได้รับผล Amp. เท่ากับจำนวนพันธมิตรที่สวมใส่「ปริศนาใต้ซากุระ」สูงสุด 3 ชั้น.\n·ตัวละครที่สวมใส่「ปริศนาใต้ซากุระ」ไม่สามารถได้รับ「อิจิโกะอิจิเอะ」."
