  },
  State_133353_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อชะตา>：หลังสวมใส่ จะไม่สามารถดูคำอธิบาย「โจมตี」,     「สกิล」,     「ปลดปล่อยความบ้าคลั่ง」ของผู้สวมใส่ได้ แต่ความเสียหาย เกราะ และการรักษาแต่ละครั้งจะเพิ่มขึ้นแบบสุ่ม[StateArg1]%～[StateArg2]%"
  },
  State_133353_Name = {
    Text = "เทพนิยายในโคลนตม"
  },
  State_133354_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เก็บรักษาหลังวงล้อมชีวิตนี้เสียชีวิต. เมื่อผู้สวมใส่เสียชีวิตและหลังสิ้นสุด [Layer] รอบถัดไปในสภาพเสียชีวิต, พันธมิตรอื่นจะได้รับ <Heal:[Heal:StateArg1]> <PVPFeatheredSeedsKeyWords:พันธุ์ขนนก> และ HP."
