  State_133372_Desc = {
    Text = "หากอยู่ในเทิร์นมิติเหนือ จะกระตุ้นเอฟเฟกต์การกระโดดข้ามจุดเอกฐาน 「การทำลายล้างจุดเอกฐาน」ยังสามารถทำให้การกระโดดข้ามจุดเอกฐานครั้งถัดไปในเทิร์นนี้เปิดใช้งานอย่างแน่นอน"
