  State_133391_Desc = {
    Text = "หากจำนวนชั้นของสภาพนี้มากกว่าหรือเท่ากับพลังชีวิตของเป้าหมาย จะลบการตัดสินโชคชะตาทั้งหมดและสังหารเป้าหมายโดยตรง การตัดสินโชคชะตาคงที่ที่มอบให้จะได้รับโบนัสจากเพิ่มพลังความเสียหาย"
