  State_133774_Desc = {
    Text = "ทุก 1 ชั้นที่มีจะเพิ่มความเสียหายที่การ์ดนี้ทำ, เพิ่มพละกำลังและความเสียหายจากหนวดสัมผัสคงที่, พิษคงที่, ผลสุดท้ายของการโต้กลับคงที่ขึ้น 2%；ผลสุดท้ายของโล่คงที่, การฟื้นฟู HP คงที่, STR▼ เพิ่มขึ้น 1%. การ์ดที่มี「สัญญาณจุดวิกฤติ」ไม่สามารถกระตุ้น「เคลื่อนผ่านมิติ」ได้."
