  },
  State_133961_Desc = {
    Text = "ทีมเดียว：หลังจากเริ่มการสำรวจจะสร้างการ์ด「สารแห่งฤดูใบไม้ผลิ」ใส่ไว้ในสำรับ：แต้มอริธเมทิกา 1, ได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[StateArg1]> แต้ม, หลังเล่นจะเปลี่ยนเป็น「ซากุระบานเต็มที่」อย่างถาวร：แต้มอริธเมทิกา 1, ได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[StateArg2]> แต้ม, หลังเล่นจะเปลี่ยนเป็น「ฮานะฟุบุกิ」อย่างถาวร：แต้มอริธเมทิกา 1, ได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[StateArg3]> แต้ม, หลังเล่นจะเปลี่ยนเป็น「อิจิโกะอิจิเอะ」อย่างถาวร：แต้มอริธเมทิกา 1, เลือก 1 จาก 3 คำสั่งกุญแจที่ปลดล็อกแบบสุ่มเพื่อปล่อยทันทีและมีผล 2 ครั้ง, หลังเล่นจะเปลี่ยนเป็น「สารแห่งฤดูใบไม้ผลิ」อย่างถาวร. การ์ดเหล่านี้ทั้งหมดมี「เก็บรักษา」."
  },
  State_133961_WeaponDesc = {
    Text = "หลังเริ่มสำรวจจะสร้างการ์ด「สารแห่งฤดูใบไม้ผลิ」1 ใบใส่ในสำรับ：ใช้พลังประมวลผล 1 ได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[StateArg1]> จุด หลังใช้จะเปลี่ยนถาวรเป็น「ซากุระบานเต็มที่」：ใช้พลังประมวลผล 1 ได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[StateArg2]> จุด หลังใช้จะเปลี่ยนถาวรเป็น「กลีบซากุระปลิว」：ใช้พลังประมวลผล 1 ได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[StateArg3]> จุด หลังใช้จะเปลี่ยนถาวรเป็น「อิจิโกะ อิจิเอะ」：ใช้พลังประมวลผล 1 เลือก 1 จาก 3 คำสั่งกุญแจสุ่มที่ปลดล็อกแล้วเพื่อปล่อยทันทีและมีผล 2 ครั้ง หลังใช้จะเปลี่ยนถาวรเป็น「สารแห่งฤดูใบไม้ผลิ」 การ์ดเหล่านี้ทั้งหมดมี「คงไว้」"
  },
  State_133994_Desc = {
    Text = "ผลสุดท้ายของความเสียหายที่การ์ดคำสั่งผู้ปลุกตื่นทั้งหมดทำ, เพิ่มพละกำลังและความเสียหายจากหนวดสัมผัสคงที่, พิษคงที่, การโต้กลับคงที่เพิ่มขึ้น [DescArg1]%, ผลของโล่คงที่, การฟื้นฟู HP คงที่, STR▼ ที่ทำให้เกิดขึ้นเพิ่มขึ้น [DescArg2]％."
