  State_139687_Desc = {
    Text = "ชีวิตอันเจิดจ้ากำลังสรรเสริญอิสรภาพ, บรรเลงเพลงแห่งชัยชนะ, สามารถถูกใช้โดยระเบิดพลังอาลีมัสของซายะเพื่อเสริมสร้างผลของมัน. สภาพนี้สะสมได้สูงสุด 4 ชั้น และจะคงอยู่หลังการต่อสู้สิ้นสุด."
