  State_143573_Desc = {
    Text = "ธรอล-กอนท์คือไพ่บัฟของพอนโทสที่ประกอบด้วย「เรด-กอนท์」「เว็กซ์-กอนท์」「สเลย์-กอนท์」รวม 3 ชนิด. เมื่อสร้าง「ธรอล-กอนท์」แบบถาวร หาก「ธรอล-กอนท์」เกิน 6 ใบ จะอัปเกรด「ธรอล-กอนท์」แบบถาวรแบบสุ่มเป็น「กอนท์แฝดสยอง」ที่แต้มอริธเมทิกา +1 แต่มีผลเพิ่มเติม 1 ครั้ง「กอนท์แฝดสยอง」ในสำรับไพ่จะนับเป็น「ธรอล-กอนท์」2 ใบ. หากทุก「ธรอล-กอนท์」ได้รับการอัปเกรดแล้ว จะนำ「แรงบัลดาลใจขั้นสูง」ที่มี<DestructionKeywords:ทำลาย> 1 ใบใส่ในมือ."
  },
