  },
  State_143595_Name = {
    Text = "หงส์ดำร่อนระบำ"
  },
  State_143597_Desc = {
    Text = "ทีมเดียว：ผลของ STR▼ ที่ผู้สวมใส่ทำให้เกิดเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>. เมื่อสลับไปยังท่าทาง「คลื่นกระหน่ำ」 ความเสียหายจากการโจมตีคริติคอลชั่วคราวจะเพิ่มขึ้น โดยปริมาณที่เพิ่มขึ้นเท่ากับ <WeaponEffect_Num:[StateArg1]%> ของดาเมจคริติคอลพื้นฐานของตนเอง คูลดาวน์ 3 รอบ."
  },
  State_143597_WeaponDesc = {
    Text = "ผลของ STR▼ ที่ผู้สวมใส่ทำให้เกิดเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>. หลังสลับไปยังท่าทาง「คลื่นกระหน่ำ」ความเสียหายจากการโจมตีคริติคอลชั่วคราวเพิ่มขึ้น <WeaponEffect_Num:[DescArg1]%> คูลดาวน์ 3 รอบ."
  },
  State_143598_Desc = {
    Text = "ทีมเดียว：ผลของ STR▼ ที่ผู้สวมใส่ทำให้เกิดเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> ทุกการสังหารศัตรู 1 ตัว จะทำให้อาลีมัสที่ฟื้นฟูรักษาแบบคงที่เมื่อสิ้นสุดรอบการสำรวจในสนามนี้ของผู้สวมใส่เพิ่มขึ้น 2 จุด สะสมได้สูงสุด <WeaponEffect_Num:[StateArg2]> ครั้ง. หลังสลับไปยังท่าทาง「คลื่นกระหน่ำ」ความเสียหายจากการโจมตีคริติคอลชั่วคราวจะเพิ่มขึ้น โดยปริมาณที่เพิ่มขึ้นเท่ากับ <WeaponEffect_Num:[StateArg1]%> ของดาเมจคริติคอลพื้นฐานของตนเอง คูลดาวน์ 3 รอบ."
  },
  State_143598_WeaponDesc = {
    Text = "ผลของ STR▼ ที่ผู้สวมใส่ทำให้เกิดเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> ทุกการสังหารศัตรู 1 ตัว จะทำให้อาลีมัสที่ฟื้นฟูรักษาแบบคงที่เมื่อสิ้นสุดรอบการสำรวจในสนามนี้ของผู้สวมใส่เพิ่มขึ้น 2 จุด สะสมได้สูงสุด <WeaponEffect_Num:[StateArg2]> ครั้ง. หลังสลับไปยังท่าทาง「คลื่นกระหน่ำ」ความเสียหายจากการโจมตีคริติคอลชั่วคราวเพิ่มขึ้น <WeaponEffect_Num:[DescArg1]%> คูลดาวน์ 3 รอบ."
  },
  State_143683_Desc = {
    Text = "การโจมตีไล่ล่าของร่างตื่นนี้ถูกผนึกไม่สามารถใช้ได้ หลังจาก [Layer] รอบ การผนึกจะถูกยกเลิก."
  },
  State_143683_Name = {
    Text = "<Seal1:โจมตีไล่ล่าผนึก>"
  },
  State_144381_Desc = {
    Text = "ไม่สามารถกระทำได้, เหลือ [DescArg1] รอบ."
  },
  State_144381_Name = {
    Text = "<Yishiganshe:การแทรกแซงจิตสำนึก>"
  },
  State_144441_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อฝ่ายเดียวกันเสียชีวิต, ตัวเองได้รับ <Energy:[Energy:StateArg1]> อาลีมัส. เมื่อฝ่ายเดียวกันฟื้นคืนชีพ, เป้าหมายได้รับ <Energy:[Energy:StateArg2]> อาลีมัส. ผลการได้รับอาลีมัสจะมีผลเฉพาะเมื่ออาลีมัสของเป้าหมายยังไม่เต็ม, มีผลเหลืออีก [Layer] ครั้ง, เมื่อหมดครั้งแล้วจะทำลายวงล้อมชีวิตนี้."
  },
  State_144441_Name = {
    Text = "จิตวิญญาณสอดประสาน"
  },
  State_144494_Desc = {
    Text = "มีผลทั้งหมด 7 ประเภท ได้แก่: จั่วไพ่ 8 ใบ, ได้รับอริธเมทิกา 6 แต้ม, ได้รับพลังงานกุญแจเงิน, ผู้ปลุกตื่นทั้งหมดได้รับอาลีมัสคงที่, ได้รับพลัง, ลดพลังของศัตรูทั้งหมดชั่วคราว, เพิ่ม DMG Amp. ชั่วคราว."
  },
  State_144494_Name = {
    Text = "<Blessing:ของขวัญ>"
  },
  State_144508_Desc = {
    Text = "「ราคาที่ต้องจ่าย」มีทั้งหมด 3 ประเภท ได้แก่ 「พลาดโอกาส」, 「คำกล่าวเกินจริง」, 「ภัยร้ายแฝงเร้น」.\n「พลาดโอกาส」: หลังจาก 2 รอบจะได้รับผล「ของขวัญ」.\n「คำกล่าวเกินจริง」: ผล「ของขวัญ」ลดลง 50％.\n「ภัยร้ายแฝงเร้น」: ให้ผลสุ่ม 1 ประเภทที่แตกต่างกันแก่ตนเอง: อ่อนแอ 2 รอบ, แตกหัก 2 รอบ, บาดเจ็บสาหัส 2 รอบ, พิษเท่ากับ 1% ของ Max HP ของตนเอง, ความว่างเปล่า 2 ชั้น, ใส่เชื่องช้า 1 ชั้นให้การ์ดสุ่ม 2 ใบในมือ, สร้างการ์ดอาการชั่วคราว 2 ใบ (ไม่สืบทอดข้ามการต่อสู้) วางไว้ด้านบนของกองไพ่ที่สุ่ม."
  },
  State_144508_Name = {
    Text = "<BlessingNegativeEffect:ราคาที่ต้องจ่าย>"
  },
  State_144519_Desc = {
    Text = "ค่าระหว่างการทดสอบ รีเฟรชหลังเริ่มต้นรอบหรือหลังเล่นการ์ด. ปัจจุบันมี [Layer] วิญญาณดินแดน."
  },
  State_144519_Name = {
    Text = "ความชำนาญดินแดนเคออสใหม่"
  },
  State_145228_Name = {
    Text = "<WormGrowth:อิ่มหนำ>"
