  State_145436_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：ความเสียหายของ「โจมตี」เพิ่มขึ้น [Arg1]% , หลังจากแต่ละ「โจมตี」ความเสียหายจะเพิ่มขึ้นอีก [Arg2]% , สูงสุดไม่เกิน [Arg3]% ."
