  State_145495_Name = {
    Text = "<CardKeyWord:ยิงคู่>"
  },
  State_145554_Desc = {
    Text = "ทีมเดียว：หลังจากเริ่มต้นการสำรวจ จะเพิ่มการ์ด 1 ใบ<Falltospace1[StateArg3]:「ก้าวสู่โลกมนุษย์」>เข้าสู่สำรับไพ่. 「ก้าวสู่โลกมนุษย์」：ใช้อริธเมทิกา 0. สร้างความเสียหายให้ศัตรูทั้งหมดเท่ากับ ATK ของผู้สวมใส่ <WeaponEffect_Num:[StateArg1]%> และ Max HP <WeaponEffect_Num:[Float:StateArg4]%> เป็น<Corrosion:กัดกร่อน>คงที่ ทำให้การ์ดคำสั่งของร่างตื่นอื่นในทุกตำแหน่งได้รับ<ErosionColorInkKeywords:การรับรู้ผิดเพี้ยน> และสับไพ่การ์ด 1 ใบ<Falltospace2[StateArg3]:「ตกขึ้นสู่เบื้องบน」>เข้ากองไพ่ที่สุ่ม. <RetainIconKeywords:เก็บรักษา>. <DepleteIconKeywords:ใช้แล้วหมด>."
  },
