  State_145699_Desc = {
    Text = "·โจมตี<StatusApplier:>ที่ล็อกเป้าก่อน, เมื่อเลือกเป้าหมายเดี่ยวจะเลือกได้เฉพาะเป้าหมายที่ล็อกเท่านั้น, ไม่สนใจยุ่วยุและการซ่อนตัว.\n·หลังจากตัวเองตาย<StatusApplier:>จะได้รับ「<PVPDerivativeCardKeywords_32:มาสู้!>」."
