  State_145709_Desc = {
    Text = "แต่ละสะสมเพิ่ม Max HP เท่ากับ 10% ของ CON ของคาราบู, 「อิ่มหนำ」สะสมได้สูงสุด 50 ชั้น. หากถึงขีดจำกัดแล้วเมื่อได้รับสภาพนี้, ทุก 1 ชั้นที่เกินจะเปลี่ยนเป็นการฟื้นฟู HP เท่ากับ 3 เท่าของปริมาณนั้น. ในการต่อสู้ที่ไม่ใช่การต่อสู้กับผู้นำแต่ละครั้งสะสมได้สูงสุด 10 ชั้น「อิ่มหนำ」. ไม่ถูกลบออกเมื่อสิ้นสุดการต่อสู้."
  },
