  State_146041_Desc = {
    Text = "ร่างตื่นนี้รู้สึกเหมือนหลุดพ้นจากความวุ่นวายของโลก.\n·ไม่สามารถทำการกระทำใดๆ ก่อนสิ้นสุดรอบ, ลดความเสียหาย 99%, หากเป้าหมายไม่มีต้านทานจะทำให้เป้าหมายได้รับต้านทาน.\n·เมื่อผลสิ้นสุดจะสร้างความเสียหายบริสุทธิ์ <Damage:[Layer]> ให้กับพันธมิตรทั้งหมด.\n·หากเป้าหมายมีต้านทานอยู่ขณะที่ใช้, จะสิ้นสุดการหลอกลวงทันทีและดาเมจต่อเป้าหมายเพิ่มเป็นสองเท่า."
