  State_148511_Desc = {
    Text = "ทีมเดียว：หลังจากเริ่มการสำรวจ, จะเพิ่มการ์ด 1 ใบ<Backupbody[StateArg3]:「จิตวิญญาณสอดประสาน」>เข้าสำรับ. 「จิตวิญญาณสอดประสาน」：แต้มอริธเมทิกา 0, หลังเล่นจะได้รับ 1 แต้มอริธเมทิกา. <RetainIconKeywords:เก็บรักษา>：สะสมการฟื้นฟู HP คงที่ <WeaponEffect_Num:[StateArg1]%> ของ CON ผู้สวมใส่ และอาลีมัสคงที่ <WeaponEffect_Num:[StateArg2]> แต้มไว้ในการ์ดนี้. หากการ์ดนี้ไม่ถูกทำลาย, สามารถภูมิคุ้มกันการตายได้หนึ่งครั้งและปล่อยการฟื้นฟู HP และอาลีมัสที่สะสมทั้งหมด, จากนั้น<DestructionKeywords:ทำลาย>การ์ดนี้."
  },
  State_148511_Name = {
    Text = "จิตวิญญาณสอดประสาน"
