  State_149094_WeaponDesc = {
    Text = "โล่พื้นฐานที่ผู้สวมใส่สร้างจากระเบิดพลังอาลีมัสเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>. หลังจากผู้สวมใส่เล่นการ์ดคำสั่งที่ทำให้<WeaknessIconKeywords:อ่อนแอ> จะทำให้การ์ดคำสั่งใบถัดไปของผู้สวมใส่เพิ่มโล่พื้นฐาน <WeaponEffect_Num:[StateArg1]%>. เมื่อใช้「เตาหลอมเลือด」จะจั่วการ์ดสกิลที่มีแต้มอริธเมทิกาสูงสุดของผู้สวมใส่ 1 ใบ, <EmbryoFusionIconKeywords:หลอมรวมตัวอ่อน> +<WeaponEffect_Num: [StateArg1]>, คูลดาวน์ 3 รอบ."
