    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อสิ้นสุดรอบ, ผู้สวมใส่สร้าง [Arg1] ความเสียหายแก่ศัตรูที่มี<HPAndShieldMax:HP และโล่สูงสุด>, <PVPMethysisKeywords:พิษ>."
  },
  State_20639_Name = {
    Text = "ของขวัญเน่าเปื่อย"
  },
  State_20640_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อสวมใส่และเมื่อเริ่มต้นรอบ จะทำให้ศัตรูทั้งหมดได้รับ <Damage:[Damage:StateArg1]> ความเสียหาย <PVPBleedingKeywords:เลือดออก> โดยจะเพิ่มความเสียหาย <PVPBleedingKeywords:เลือดออก> +[StateArg2] สำหรับทุกใบไพ่บนมือของเป้าหมาย。"
  },
  State_20640_Name = {
    Text = "งานสำราญเลือด"
  },
  State_20641_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อตัวละครเสียชีวิตจะมอบ [StateArg1] ชั้นของ<PVPProtectiveKeywords:บาเรีย> ให้กับพันธมิตรอื่น"
  },
  State_20641_Name = {
    Text = "กายวิภาคความตาย"
  },
  State_20642_Desc = {
    Text = "<PVPHoldingKeywords:ถือครอง>：ทุกครั้งที่คุณเล่นการ์ดใบนี้ การ์ดนี้จะกลายเป็น「วงล้อมชีวิต」แบบสุ่มอื่นและลดการใช้พลังการคำนวณลง –1."
  },
  State_20642_Name = {
    Text = "จิตวิญญาณเกิด"
  },
  State_20643_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：หลัง「ระเบิดพลัง」ได้รับ [Arg1] อริธเมทิกา, <DelayKeywords:ความหน่วง 1>：หัก [Arg2] อริธเมทิกา."
  },
  State_20643_Name = {
    Text = "อาการจำไม่ได้"
  },
  State_20644_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อสวมใส่จะสร้างความเสียหาย [StateArg2] แก่ตัวเอง,     <PVPEntanglementKeywords:บ่วงรัด>.ทุกครั้งที่มีพันธมิตรฝ่ายเดียวกันเสียชีวิต 1 คน <StrongEffectKeywords:Amp.>+[StateArg1]."
  },
  State_20644_Name = {
