  },
  State_20645_Name = {
    Text = "กระเป๋าสะพายหลังผจญภัย"
  },
  State_20646_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ตี」ความเสียหายเพิ่มขึ้น [StateArg1]%,     「ระเบิดพลัง」หลังฟื้นฟูตัวเอง <Heal:[Heal:StateArg2]> ชีวิต."
  },
  State_20646_Name = {
    Text = "กลืนกินเพลงบรรเลงกล่อม"
  },
  State_20647_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ระเบิดพลัง」จะใส่ [StateArg1] ใบ<PVPDerivativeCardKeywords_11:「การแลกเปลี่ยนที่ไม่เท่าเทียม」>ลงในมือ."
  },
  State_20647_Name = {
    Text = "ท่ามกลางพายุฝน"
  },
  State_20648_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อเริ่มต้นเทิร์น จะได้รับผลบวก<PVPWonderfulEffectKeywords:ผลวิเศษ> และเมื่อศัตรูใช้「คำสั่งกุญแจ」ครั้งแรกในแต่ละเทิร์น จะนำ「ทัศนียภาพอันงดงาม」[StateArg1] ใบเข้ามือ。"
  },
  State_20648_Name = {
    Text = "งานระเริงไร้เสียง"
  },
  State_20649_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ระเบิดพลัง」นำ「ทักษะ」สุดท้ายที่เล่นในรอบที่แล้วกลับเข้ามาในมือ และลดการใช้พลังการคำนวณลง –1 หากเกิดผลลัพธ์นี้หลายครั้งจะย้อนกลับไปข้างหน้า."
  },
  State_20649_Name = {
    Text = "เวลาย้อนกลับ"
  },
  State_20650_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อชะตา>：เมื่อสวมใส่จะทำให้ตัวเอง<ComaKeywords:สลบ> ก่อน「การระเบิดแห่งความบ้าคลั่ง」จะสลายสถานะเชิงบวกของศัตรูทั้งหมด"
  },
  State_20650_Name = {
    Text = "เพ้อคลั่ง"
  },
  State_20651_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อจบเทิร์น จั่วการ์ด [StateArg1] ใบ。"
  },
  State_20651_Name = {
    Text = "ความโลภ"
  },
  State_20652_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：หลังจาก「ระเบิดพลัง」จะสร้างความเสียหาย [StateArg1] ให้กับศัตรูทั้งหมด,     <DisarmKeywords:ชาบด>."
  },
  State_20652_Name = {
    Text = "ลงทัณฑ์"
  },
  State_20653_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「การโจมตี」สามารถเลือกเป้าหมายและหักลด <Energy:[Energy:StateArg1]> ความคลั่งของเป้าหมายได้。"
  },
  State_20653_Name = {
    Text = "ลอยล่องในห้วงตัณหา"
  },
  State_20654_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อเริ่มต้นเทิร์น จะทำให้ตัวเอง<PVPSeriousInjuryKeywords:บาดเจ็บสาหัส> และได้รับ <Damage:[Damage:StateArg1]> ชั้น<PVPCorrosionKeywords:ตราประทับแห่งความผิด>. เมื่อสิ้นสุดเทิร์น จะ<ReinforceKeywords:เสริมความแข็งแกร่ง>ตัวเอง."
  },
  State_20654_Name = {
    Text = "ราชโองการของราชินี"
  },
  State_20655_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ตี」ความเสียหายเพิ่มขึ้น [StateArg1]%,     「ตี」เลือกเป้าหมายได้."
  },
  State_20655_Name = {
    Text = "โปรดปราน"
  },
  State_20656_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ทักษะ」ที่ก่อให้เกิดความเสียหาย การรักษา และผลของโล่เพิ่มขึ้น [StateArg1]% ，หากใช้「ทักษะ」แล้วไม่มี<PVPProtectiveKeywords:บาเรีย>จะได้รับ 1 ชั้น。"
  },
  State_20656_Name = {
    Text = "บทส่งท้าย"
  },
  State_20657_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：ทุกครั้งที่คู่ต่อสู้เล่น「ทักษะ」ใบที่ [StateArg1] ในแต่ละเทิร์น จะทำการคัดลอกการ์ดนั้นที่ลดพลังการคำนวณลง - [StateArg2] และใส่เข้าไปในมือของคุณ。"
  },
  State_20657_Name = {
    Text = "ปรีชาญาณ"
  },
  State_20658_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「โจมตี」ทุกครั้งที่โจมตีเป้าหมายหนึ่งเป้าหมาย จะได้รับ [StateArg1] พลังการคำนวณ。"
  },
  State_20658_Name = {
    Text = "บัลลาดพันธนาการ"
  },
  State_20659_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：หลังจากเสียชีวิต เมื่อเริ่มต้นเทิร์นถัดไป <PVPResurrectionKeywords:ฟื้นคืนชีพ> ตัวเองและได้รับ <Heal:[Heal:StateArg1]> HP และ<Block:[Block:StateArg2]> โล่ และทำลาย「วงล้อมชีวิต」นี้。"
  },
  State_20659_Name = {
    Text = "กำลังวังชา"
  },
  State_20660_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ระเบิดพลัง」หลังจากนั้นทำให้เพื่อนทั้งหมดได้รับ <Block:[Block:StateArg1]> โล่."
  },
  State_20660_Name = {
    Text = "กำแพงแห่งจิตใจ"
