  },
  State_20661_Name = {
    Text = "หนทางที่หลงหาย"
  },
  State_20662_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อสิ้นสุดรอบ, ทุกๆ 1 จุด<PVPCapKeywords:ขีดจำกัดอริธเมทิกา>จะสร้าง [Arg1] <PVPBleedingKeywords:เลือดออก>ให้กับศัตรูที่มี<HPAndShieldMin:HP และโล่ต่ำสุด>, รวมสร้างความเสียหาย <Damage:[Damage:Arg2]> <PVPBleedingKeywords:เลือดออก>."
  },
  State_20662_Name = {
    Text = "ซ่อนตัวในความมืด"
  },
  State_20663_Desc = {
