  },
  State_20663_Name = {
    Text = "ทลายโซ่ตรวน"
  },
  State_20664_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ทักษะ」ทำให้ตัวเองได้รับ<ReinforceKeywords:เสริมความแข็งแกร่ง>."
  },
  State_20664_Name = {
    Text = "ปฏิญาณอัศวิน"
  },
  State_20665_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อตัวเองขับไล่ความลบหากไม่มีสภาพลบที่สามารถขับไล่ได้จะฟื้นฟูรักษา <Heal:[Heal:StateArg1]> HP. เมื่อสิ้นสุดรอบ <DelayKeywords:ความหน่วง 1>:  ขับไล่ความลบของตัวเอง."
  },
  State_20665_Name = {
    Text = "ใบเรือแห่งญาณสอดส่อง"
  },
  State_20666_Desc = {
