  },
  State_20666_Name = {
    Text = "แด่เพื่อนรัก"
  },
  State_20667_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：ความเสียหายของ「ทักษะ」ใบแรกของผู้สวมใส่ที่เล่นในแต่ละเทิร์นเพิ่มขึ้น [StateArg1]%."
  },
  State_20667_Name = {
    Text = "ดาบไททัน"
  },
  State_20668_Desc = {
