  },
  State_20669_Name = {
    Text = "จารึกศักดิ์สิทธิ์"
  },
  State_20670_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ตี」ทำให้เกิด<PVPSeriousInjuryKeywords:บาดเจ็บสาหัส> ความเสียหายเพิ่มขึ้น [StateArg1]% แต่ทำให้ตัวเองสูญเสียชีวิตที่ทำให้เกิดความเสียหายครึ่งหนึ่ง。"
  },
  State_20670_Name = {
