  State_3824_Desc = {
    Text = "ทีมเดียว：ความเสียหายพื้นฐานของระเบิดพลังของผู้สวมใส่เพิ่มขึ้น [StateArg1]%。เมื่อเริ่มต้นการสำรวจ ผู้สวมใส่จะเข้าสู่สถานะบุคลิกภาพนักวิชาการ หลังจากผู้สวมใส่ปล่อยระเบิดพลัง จะสลับระหว่างบุคลิกภาพนักวิชาการและบุคลิกภาพตัวตลก。\nบุคลิกภาพนักวิชาการ：เมื่อสิ้นสุดเทิร์น ผู้สวมใส่จะได้รับ <WeaponEffect_Num:[StateArg2]> อาลีมัส。\nบุคลิกภาพตัวตลก：เมื่อสิ้นสุดเทิร์น อัตราคริติคอลและความเสียหายคริติคอลของผู้สวมใส่ <WeaponEffect_Num:+[StateArg3]%>。"
  },
