  State_47189_Name = {
    Text = "สลับเป็นบุคลิกภาพคลุ้มคลั่ง. คาโร·บุคลิกภาพซึมเศร้า：<EmbryoFusionIconKeywords:หลอมรวมตัวอ่อน> +[Blood:StateArg5] สะสม [StateArg6] จุดปริมาณการฟื้นฟูรักษาเตาหลอมเลือด"
