  State_47192_Name = {
    Text = "บุคลิกภาพซึมเศร้า：ยังทำให้ผู้ปลุกตื่นอื่นๆ ได้รับความคลั่ง [DescArg1] เท่า.บุคลิกภาพคลั่ง：ได้รับความคลั่งเพิ่มอีก [DescArg2] เท่า"
  },
  State_47199_Name = {
    Text = "สลับเป็นบุคลิกภาพซึมเศร้า เนื้อและเลือด·คลั่ง：ความเสียหายได้รับโบนัส [DescArg1] เท่าจาก<PowerIconKeywords:พละกำลัง> และทำให้เป้าหมายได้รับความเสียหาย 200% จาก<BleedingIconKeywords:เลือดออก>，ได้รับ [StateArg7] คะแนน<PowerIconKeywords:พละกำลัง>"
  },
  State_47204_Name = {
    Text = "สลับไปยังบุคลิกภาพคลั่ง。เคออส·ซึมเศร้า：ได้รับ <Posse:[StateArg1]> คะแนนพลังงานกุญแจเงิน，การใช้คำสั่งกุญแจครั้งถัดไปจะมีผล 2 ครั้ง"
  },
  State_47206_Name = {
    Text = "เปลี่ยนเป็นบุคลิกภาพคลั่ง。เอควอ·ซึมเศร้า：<WeaknessIconKeywords:อ่อนแอ> และ <VulnerabilityIconKeywords:เปราะบาง> เป้าหมาย 2 รอบ สร้างหนวดสัมผัส 1 เส้น <TentacleInjurieIconKeywords:ความเสียหายจากหนวด> + [TentaclePower:StateArg3]"
  },
  State_47209_Name = {
    Text = "สลับเป็นบุคลิกภาพซึมเศร้า. อัลตร้า·คลั่ง: ได้รับ<RetaliateIconKeywords:การโต้กลับ>ที่สร้างความเสียหาย 15%, จากนั้นสร้าง<FixedDamage:ความเสียหายบริสุทธิ์>เท่ากันให้กับศัตรูอื่น. ทุกครั้งที่เล่นการ์ด「แรงบัลดาลใจ」1 ใบในรอบนี้, ทำให้ความเสียหายนั้นเพิ่มขึ้น [StateArg9] จุดในรอบนี้, สูงสุด [StateArg10] จุด"
  },
  State_47211_Name = {
