  },
  State_47212_Name = {
    Text = "ทำให้「24」สลับระหว่างบุคลิกภาพซึมเศร้าและบุคลิกภาพคลั่ง และตามดินแดนและบุคลิกภาพในปัจจุบัน จะกระตุ้นผลเพิ่มเติม"
  },
  State_47216_Name = {
