  State_47500_Name = {
    Text = "บุคลิกภาพซึมเศร้า：ได้รับ <Energy: [DescArg1] > คะแนนความคลั่งเพิ่มเติม.<AwakerCard_24Lost:บุคลิกภาพคลั่ง：ได้รับโล่เพิ่ม [DescArg2] ครั้ง>"
  },
  State_47517_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อจบเทิร์น จากเป้าหมายตื่นอื่น ทิ้งการ์ด [StateArg1] ใบ หากทิ้งการ์ดสำเร็จจะจั่ว [StateArg2] ใบ."
  },
  State_47517_Name = {
    Text = "ความมุ่งมั่นของปลาคอดเงิน"
  },
  State_47518_Name = {
    Text = "ตัวนับความมุ่งมั่นของปลาคอดเงิน__「สำหรับพัฒนาเท่านั้น」"
  },
  State_47528_Desc = {
    Text = "รอบนี้「ตี」+ [DescArg1]% ความเสียหาย<PVPPenetrateKeywords:ทะลวง 1>."
  },
  State_47528_Name = {
    Text = "อัสดงค์อสูรดารา"
  },
  State_47530_Desc = {
    Text = "นับเป็น「ทักษะ」ที่ใช้ครั้งล่าสุดในรอบนี้"
  },
  State_47530_Name = {
    Text = "<CardKeyWord:การจำลองการแสดง>"
  },
  State_47557_Desc = {
    Text = "ทีมเดียว：หลังจากเริ่มการสำรวจ ผู้สวมใส่จะเข้าสู่สภาพบุคลิกมนุษย์ปลาเงิน. หลังจากผู้สวมใส่ปล่อยระเบิดพลังอาลีมัส จะสลับระหว่างบุคลิกมนุษย์ปลาเงินและบุคลิกแมว.\nบุคลิกมนุษย์ปลาเงิน：หลังจากผู้สวมใส่สร้างดาเมจสกิลกดใช้ จะได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[StateArg1]> แต้ม. บุคลิกแมว：หลังจากผู้สวมใส่สร้างดาเมจสกิลกดใช้ ความเสียหายจากการโจมตีคริติคอลชั่วคราวของผู้สวมใส่ <WeaponEffect_Num:+[StateArg2]%>. ทั้งสองผลนี้ใช้โอกาสร่วมกันสูงสุด 5 ครั้งต่อรอบ."
  },
  State_47557_WeaponDesc = {
    Text = "หลังจากเริ่มการสำรวจ ผู้สวมใส่จะเข้าสู่สภาพบุคลิกมนุษย์ปลาเงิน. หลังจากผู้สวมใส่ปล่อยระเบิดพลังอาลีมัส จะสลับระหว่างบุคลิกมนุษย์ปลาเงินและบุคลิกแมว.\nบุคลิกมนุษย์ปลาเงิน：หลังจากผู้สวมใส่สร้างดาเมจสกิลกดใช้ จะได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[StateArg1]> แต้ม. บุคลิกแมว：หลังจากผู้สวมใส่สร้างดาเมจสกิลกดใช้ ความเสียหายจากการโจมตีคริติคอลชั่วคราวของผู้สวมใส่ <WeaponEffect_Num:+[StateArg2]%>. ทั้งสองผลนี้ใช้โอกาสร่วมกันสูงสุด 5 ครั้งต่อรอบ."
  },
  State_47822_Desc = {
    Text = "หากในรอบถัดไปได้รับ「อัมพาต」อีกครั้ง, 「ตี」ทั้งหมดของเป้าหมายจะกลายเป็น「ภาพหลอน」, ไม่สามารถขจัดได้, ต่อเนื่องจนถึงสิ้นสุดรอบถัดไป."
  },
  State_47822_Name = {
    Text = "รู้สึกชาบ้างแล้ว"
  },
  State_47825_Desc = {
    Text = "ผลนี้จะถูกกระตุ้นหลังจากเริ่มต้นรอบไปแล้วหลายรอบ."
  },
  State_47825_Name = {
    Text = "<CardKeyWord:หน่วงเวลา>"
  },
  State_47826_Desc = {
    Text = "·เมื่อเป้าหมายอยู่ในสถานะ「อัมพาต」ดาเมจจะเพิ่มเป็นสองเท่า มิฉะนั้น「ตี」ของมันจะใช้ไม่ได้ในรอบนี้\n·หากอยู่ในสถานะ「อัมพาต」ติดต่อกัน 2 รอบ「ตี」ทั้งหมดของมันจะกลายเป็น「ภาพหลอน」."
  },
  State_47826_Name = {
    Text = "<WeaknessColour:ชาบด>"
  },
  State_47827_Desc = {
    Text = "ทุกชั้นจะลดความเสียหายทั้งหมดที่เกิดขึ้นในการต่อสู้ครั้งนี้ลง 1 หน่วย ไม่สามารถขจัดได้."
  },
  State_47827_Name = {
    Text = "<WeaknessColour:พละกำลังลดลง>"
  },
  State_47828_Desc = {
    Text = "·เมื่อใส่จะสร้างความเสียหายเท่ากับจำนวนชั้น หากเป้าหมายอยู่ในสภาพ「บ่วงรัด」ความเสียหายจะเพิ่มเป็นสองเท่า มิฉะนั้นจะทำให้วงล้อมชีวิตที่เป้าหมายติดตั้งไม่มีผลจนกว่าจะสิ้นสุดเทิร์น."
  },
  State_47828_Name = {
    Text = "<WeaknessColour:พันตัว>"
  },
  State_47830_Desc = {
    Text = "เมื่อใช้งาน จะทำการลบโล่และการรักษาที่ล่าช้าจากเป้าหมาย ก่อนสิ้นสุดเทิร์น ความสามารถในการรักษาและโล่ที่ได้รับจะลดลง 50%。"
  },
  State_47830_Name = {
    Text = "<PVPVulnerabilityIconColour:บาดเจ็บหนัก>"
  },
  State_47831_Desc = {
    Text = "ไม่สามารถทำการกระทำใดๆ ได้จนกว่าจะสิ้นสุดรอบ, หลังจากได้รับดาเมจหมดแรงจะทำให้เป้าหมายได้รับต้านทาน. เมื่อมีต้านทานและได้รับดาเมจหมดแรงอีกครั้ง จะหักล้างผลหมดแรงและทำให้ดาเมจเพิ่มเป็นสองเท่า."
  },
  State_47831_Name = {
