  State_47889_Name = {
    Text = "เอควอ：ความเสียหายที่「24」ก่อขึ้นได้รับโบนัส<TentacleInjurieIconKeywords:ความเสียหายจากหนวด> [StateArg2]% และก่อให้เกิด<IntoxicationIconKeywords:พิษ> 10% ของความเสียหาย. ระเบิดพลังของ「24」สามารถกระตุ้น<IntoxicationIconKeywords:พิษ> [StateArg6]％ ของศัตรู"
