  State_48078_Name = {
    Text = "<CardKeyWord:สตาร์ไชน์มิเมซิส>"
  },
  State_48099_Desc = {
    Text = "เมื่อจบเทิร์น「24」จะได้รับอาลีมัส [DescArg1] คะแนน ทุกครั้งที่「24」ปล่อยระเบิดพลัง คะแนนความคลั่งที่ได้รับจะเพิ่มขึ้น 1。"
  },
  State_48099_Name = {
    Text = "การวิจัยพฤติกรรมของปาวลوف"
  },
  State_48099_WeaponDesc = {
    Text = "ผู้สวมใส่จะได้รับอาลีมัส 3 คะแนนเมื่อจบเทิร์น หากการชาร์จความคลั่งของผู้สวมใส่มากกว่า 10 จะได้รับอาลีมัสเพิ่มเติม 2 คะแนน。"
  },
  State_48100_Name = {
    Text = "สถานะ@24 การวิจัยพฤติกรรมพาฟลอฟ จำนวน"
  },
  State_48100_WeaponDesc = {
    Text = "ผู้สวมใส่ได้รับอาลีมัส 3 จุดเมื่อจบรอบ หากการชาร์จความคลั่งของผู้สวมใส่มากกว่า 10 จะได้รับอาลีมัสเพิ่มเติม 2 จุด。"
  },
  State_48107_Desc = {
    Text = "「ทักษะ」ใบแรกของผู้สวมใส่ที่เล่นในแต่ละรอบ จะเพิ่มความเสียหาย [StateArg1]％."
  },
  State_48107_Name = {
    Text = "ดาบไททัน"
  },
  State_48108_Desc = {
    Text = "หลังจากผู้สวมใส่เล่น「ทักษะ」ใบแรกในแต่ละเทิร์น จะทำการคัดลอกการ์ดนั้นที่ลดพลังการคำนวณลง - [StateArg1] และสับเข้าไปในกองไพ่ที่สุ่ม。"
  },
  State_48108_Name = {
    Text = "ฟูเอ็ตเต้"
  },
  State_48110_Desc = {
    Text = "「ทักษะ」ทำให้การ「ตี」ครั้งถัดไปในรอบนี้เปลี่ยนเป็นศัตรูแบบสุ่มและโจมตีศัตรูแบบสุ่มเพิ่มเติม [StateArg1] ตัว。"
  },
  State_48110_Name = {
    Text = "คนในกระจก"
  },
  State_48140_Desc = {
    Text = "เมื่อเริ่มการสำรวจ，「24」เข้าสู่สถานะบุคลิกภาพซึมเศร้า。\n<School_1:เคออส·ซึมเศร้า>: ได้รับ <Posse:[StateArg1]> หน่วยพลังงานกุญแจเงิน คำสั่งกุญแจครั้งถัดไปจะใช้ได้ 2 ครั้ง。\n<School_1:เคออส·คลั่ง>: สร้างความเสียหาย 3 ครั้ง ทำให้ความเสียหายทั้งหมดที่「24」สร้างเพิ่มขึ้น [StateArg2] หน่วย。\n<School_2:เอควอ·ซึมเศร้า>: <WeaknessIconKeywords:อ่อนแอ>และ<VulnerabilityIconKeywords:เปราะบาง>เป้าหมายเป็นเวลา 2 รอบ สร้างหนวดสัมผัส 1 ตัว <TentacleInjurieIconKeywords:ความเสียหายจากหนวด>+ [StateArg3]。\n<School_2:เอควอ·คลั่ง>: ความเสียหายนี้ได้รับ [StateArg4]% <TentacleInjurieIconKeywords:ความเสียหายจากหนวด>เพิ่มเติม และทำให้ศัตรูทั้งหมดได้รับ<IntoxicationIconKeywords:พิษ> 30% ของความเสียหายที่สร้าง。\n<School_3:คาโร·ซึมเศร้า>: <EmbryoFusionIconKeywords:หลอมรวมตัวอ่อน> +[Blood:StateArg5]，สะสม [StateArg6] หน่วยการฟื้นฟูเตาหลอมเลือด。\n<School_3:คาโร·คลั่ง>: ความเสียหายได้รับโบนัส 6 เท่า<PowerIconKeywords:พละกำลัง>และทำให้เป้าหมายได้รับ<BleedingIconKeywords:เลือดออก> 200% ของความเสียหายที่สร้าง พร้อมได้รับ [StateArg7] หน่วย<PowerIconKeywords:พละกำลัง>。\n<School_4:อัลตร้า·ซึมเศร้า>: เพิ่มการ์ด「แรงบัลดาลใจ」 2 ใบเข้ามือ ทำให้<PowerIconKeywords:พละกำลัง>ของเป้าหมายลดลงชั่วคราว [StateArg8] หน่วย。\n<School_4:อัลตร้า·คลั่ง>: ได้รับ<RetaliateIconKeywords:การโต้กลับ> 15% ของความเสียหายที่สร้าง จากนั้นทำให้ศัตรูอื่นๆ ได้รับ<FixedDamage:ความเสียหายบริสุทธิ์>เท่ากัน ในรอบนี้ สำหรับทุกครั้งที่เล่นการ์ด「แรงบัลดาลใจ」 1 ใบ จะทำให้ความเสียหายนี้เพิ่มขึ้น [StateArg9] หน่วยในรอบนี้ สูงสุดเพิ่มขึ้น [StateArg10] หน่วย。"
  },
  State_48140_Name = {
    Text = "ขอบเขตและผลของบุคลิกภาพ"
  },
  State_48141_Desc = {
    Text = "<School_1:เคออส>：「24」อัตราคริติคอลและดาเมจคริติคอล +[StateArg4]%.ทุกครั้งที่ใช้คำสั่งกุญแจ จะทำให้ดาเมจสุดท้ายจากระเบิดพลังของ「24」เพิ่มขึ้น [StateArg1]%.\n<School_2:เอควอ>：「24」ความเสียหายที่สร้างจะได้รับการเพิ่มขึ้น [StateArg2]% จาก<TentacleInjurieIconKeywords:ความเสียหายจากหนวด> และทำให้เกิดความเสียหาย 10% ของ<IntoxicationIconKeywords:พิษ>.「24」การระเบิดพลังของจะสามารถกระตุ้นศัตรู 50% ของ<IntoxicationIconKeywords:พิษ>.\n<School_3:เนื้อและเลือด>：「24」ทุกครั้งที่ใช้ 1 คะแนนอริธเมทิกา<EmbryoFusionIconKeywords:หลอมรวมตัวอ่อน> +[Blood:DescArg1],      จะได้รับ [StateArg3] คะแนน<PowerIconKeywords:STR>.「24」การระเบิดพลังจะได้รับโบนัส STR เพิ่มเติม 300%\n<School_4:อัลตร้า>：「24」ความเสียหายที่สร้างจะได้รับโบนัสความเสียหายจาก<RetaliateIconKeywords:เคาน์เตอร์> [StateArg5]%,      และเมื่อสิ้นสุดเทิร์น จะสับไพ่ 1 ใบ「แรงบัลดาลใจ」ลงในกองทิ้ง ขีดจำกัดไพ่บนมือ +2."
