    Text = "โล่ที่ผู้สวมใส่สร้างขึ้นจะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> หลังจากปลดล็อกกุญแจลับแล้ว ผู้ปลุกตื่นทั้งหมดจะได้รับอัตราการคริติคอลชั่วคราว <WeaponEffect_Num:[StateArg2]%> และดาเมจคริติคอล แต่จะต้องมีการบูชายัญ [DescArg1] คะแนน หากดินแดนปัจจุบันคือ「เอควอ」หลังจากปลดล็อกกุญแจลับแล้ว จะทำให้ความเสียหายจากหนวดสัมผัสเพิ่มขึ้น [DescArg2] คะแนน。"
