  },
  State_57767_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อจบเทิร์น หัก <Energy:[Energy:StateArg1]> อาลีมัสเปลี่ยนเป็น<PVPDerivativeCardKeywords_12:「ปณิธานอันเล็กน้อย」>，หากการเปลี่ยนแปลงล้มเหลวจะได้รับ <Energy:[Energy:StateArg2]> อาลีมัส。"
