  },
  State_57768_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：「ทักษะ」ความเสียหายเพิ่มขึ้น [StateArg1]%.หลังจาก「ระเบิดพลัง」จะฟื้นฟูชีวิตที่สูญเสียไปของตนเอง [StateArg2]%."
