  },
  State_58144_WeaponDesc = {
    Text = "อัตราการโจมตีคริติคอลในด่านนี้เพิ่มขึ้น [Layer] % ｡"
  },
  State_58259_Desc = {
    Text = "ทีมเดียว: อัตราคริติคอลของผู้สวมใส่เพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> หลังจากผู้สวมใส่สังหารศัตรู จะได้รับ <WeaponEffect_Num:[StateArg2]> รอยดำ ในการสำรวจสามารถทริกเกอร์ได้สูงสุด 3 ครั้ง หลังจากทริกเกอร์ 3 ครั้ง จะทำให้ผู้สวมใส่เพิ่มอัตราคริติคอล <WeaponEffect_Num:[StateArg3]%> ตลอดการสำรวจนี้。"
  },
  State_58259_WeaponDesc = {
    Text = "อัตราคริติคอลของผู้สวมใส่เพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> หลังจากผู้สวมใส่สังหารศัตรูจะได้รับ <WeaponEffect_Num:[DescArg2]> รอยดำ สูงสุด 3 ครั้งในระหว่างการสำรวจ([DescArg1]/3) หลังจากtrigger 3 ครั้ง ในการสำรวจครั้งนี้อัตราคริติคอลของผู้สวมใส่จะเพิ่มขึ้นถาวร <WeaponEffect_Num:[StateArg3]%>."
  },
  State_58297_Desc = {
    Text = "ไรเกอร์สังหารศัตรูจะได้รับ [DescArg3] รอยดำ โดยมีผลสูงสุด 5 ครั้งต่อการสำรวจ.([DescArg1]/5) \n หลังจากการต่อสู้เพื่อรับรอยดำ 50/125/250 รอย ขีดจำกัดสิ่งสร้างเพิ่มขึ้น 1 และเมื่อการต่อสู้สิ้นสุดลงให้เลือก「มรดกของความวุ่นวาย」หนึ่งชิ้นเพื่อเพิ่มลงในรายการสิ่งสร้าง.(ได้รับ [DescArg2] คะแนนรอยดำ)"
  },
  State_58297_Name = {
    Text = "ผู้ชนะได้ทุกอย่าง"
  },
  State_58447_Desc = {
    Text = "รวมถึงเรลิกสามชิ้นต่อไปนี้: \n「เสื้อโค้ทลมโชคดี」: อัตราคริติคอลของผู้ปลุกตื่นทั้งหมดเพิ่มขึ้น 10%。ผลสุ่มของไรเกอร์และลูกเต๋าทั้งหมดจะไม่มีค่าต่ำสุด。\n<TentacleInjurieIconKeywords:อัปเกรด>: เปลี่ยนอัตราคริติคอลเพิ่มขึ้นเป็น 15% ทำให้ค่าผลสุ่มสูงสุดเพิ่มขึ้น 1。\n「ลูกเต๋าสิบสองหน้า」: ทุกครั้งที่ปลดล็อกกุญแจ จะนำการ์ด「<C05_yansheng1:ลูกเต๋าสิบสองหน้า>」1 ใบใส่ไว้ในมือ。\n<TentacleInjurieIconKeywords:อัปเกรด>: เปลี่ยนเป็นนำการ์ด「<C05_yansheng2:ลูกเต๋าสิบสองหน้าส่องประกาย>」1 ใบใส่ไว้ในมือ。\n「ปุ่มปากใหญ่」: เมื่อเริ่มต้นรอบและเมื่อทริกเกอร์ผลสุ่มของไรเกอร์หรือลูกเต๋า จะได้รับพลังงานกุญแจเงิน 50 คะแนนและความเสียหายคริติคอล 2% โดยสามารถได้รับสูงสุด 30% ความเสียหายคริติคอล。\n<TentacleInjurieIconKeywords:อัปเกรด>: เปลี่ยนเป็นได้รับพลังงานกุญแจเงิน 100 คะแนนและความเสียหายคริติคอล 4% โดยสามารถได้รับสูงสุด 50% ความเสียหายคริติคอล。"
  },
