  State_60592_Desc = {
    Text = "ทีมเดียว：เมื่อเริ่มการสำรวจ จะสับไพ่「กุญแจเงินอรุณรุ่ง」1 ใบเข้ากองไพ่ที่สุ่มพร้อมแนบ<DestructionKeywords:ทำลาย>. หลังจากปล่อยคำสั่งกุญแจ ดาเมจคริติคอลของผู้สวมใส่จะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>. เมื่อผู้สวมใส่สร้างดาเมจสกิลกดใช้ จะได้รับพลังงานกุญแจเงินเท่ากับ <WeaponEffect_Num:[StateArg2]%> ของฟื้นฟูพลังงานกุญแจเงินของผู้สวมใส่ และอัตราคริติคอลชั่วคราว <WeaponEffect_Num:[StateArg3]%> สูงสุด 5 ครั้งต่อรอบ."
  },
  State_60592_WeaponDesc = {
    Text = "เมื่อเริ่มการสำรวจ จะสับไพ่「กุญแจเงินอรุณรุ่ง」1 ใบเข้ากองไพ่ที่สุ่มพร้อมแนบ<DestructionKeywords:ทำลาย>. หลังจากปล่อยคำสั่งกุญแจ ดาเมจคริติคอลของผู้สวมใส่จะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>. เมื่อผู้สวมใส่สร้างดาเมจสกิลกดใช้ จะได้รับพลังงานกุญแจเงิน <WeaponEffect_Num:[DescArg1]> แต้ม และอัตราคริติคอลชั่วคราว <WeaponEffect_Num:[StateArg3]%> สูงสุด 5 ครั้งต่อรอบ."
  },
  State_60594_Desc = {
    Text = "เฉพาะในทีม: หลังจากจบเทิร์น ผู้สวมใส่จะได้รับความคลั่ง 5 หน่วย หลังจากผู้สวมใส่ปลดปล่อยระเบิดพลัง อัตราคริติคอล,ดาเมจคริติคอล,โล่ และการฟื้นฟูเลือดของการ์ดคำสั่งใบถัดไปที่เล่นโดยผู้สวมใส่ในรอบนี้จะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>。"
