  State_65346_Name = {Text = "Frostfall"},
  State_65358_Desc = {
    Text = "ทีมเดียว: ความเสียหายพื้นฐานที่ผู้สวมใส่สร้างขึ้นจะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> ก่อนที่ผู้สวมใส่จะปล่อยระเบิดพลัง ขีดจำกัดไพ่บนมือชั่วคราว +1 และจั่วการ์ดคำสั่งของผู้สวมใส่ 1 ใบ หากดินแดนปัจจุบันเป็น「เนื้อและเลือด」 เมื่อผู้สวมใส่กระตุ้นกลืนกิน ความเสียหายจากการโจมตีคริติคอลชั่วคราวจะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> โดยสามารถเกิดขึ้นได้สูงสุด 1 ครั้งต่อรอบ。"
  },
  State_65358_WeaponDesc = {
    Text = "ผู้สวมใส่จะเพิ่มความเสียหายพื้นฐาน <WeaponEffect_Num:[StateArg1]%> ตอนที่ผู้สวมใส่ใช้พลังคลั่งไคล้ก่อนถึงขีดจำกัดของการ์ดบนมือ +1 และจั่วการ์ดคำสั่งของผู้สวมใส่ 1 ใบ หากขอบเขตปัจจุบันเป็น 「เนื้อและเลือด」 เมื่อผู้สวมใส่กระตุ้นการกลืนกิน จะเพิ่มความเสียหายคริติคอลชั่วคราว <WeaponEffect_Num:[StateArg1]%> สามารถเปิดใช้งานได้สูงสุด 1 ครั้งต่อรอบเท่านั้น。"
  },
  State_65360_Desc = {
    Text = "ทีมเดียว: ความเสียหายพื้นฐานที่ผู้สวมใส่สร้างขึ้นจะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> เมื่อเริ่มต้นการต่อสู้ ผู้สวมใส่จะได้รับ 25 ชั้น「หยาดน้ำฟ้า」 หลังจากผู้สวมใส่เล่นการ์ด จะได้รับ 2 หน่วยอาลีมัสและลบออก 1 ชั้น เมื่อ「หยาดน้ำฟ้า」ถูกลบออกทั้งหมด ผู้สวมใส่จะได้รับอัตราคริติคอล <WeaponEffect_Num:[StateArg2]%>。"
  },
  State_65360_WeaponDesc = {
    Text = "ความเสียหายพื้นฐานที่ผู้สวมใส่สร้างขึ้นเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>。เมื่อเริ่มต่อสู้ ผู้สวมใส่จะได้รับ 25 ชั้น「หยาดน้ำฟ้า」，หลังจากผู้สวมใส่เล่นการ์ดจะได้รับ 2 ความคลั่งและลบ 1 ชั้นออก。「หยาดน้ำฟ้า」 ถูกลบออกอย่างสมบูรณ์แล้ว ผู้สวมใส่จะได้รับอัตราคริติคอล <WeaponEffect_Num:[StateArg2]%> (ชั้นหยาดน้ำฟ้าที่เหลืออยู่ [DescArg1] ชั้น)"
