  State_71155_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ลีห์จะได้รับความคลั่ง 15 หน่วย ทุกครั้งที่สูญเสีย HP จะได้รับพละกำลัง 8 คะแนน โดยสามารถสะสมได้สูงสุด 10 ครั้งต่อการต่อสู้ เมื่อสะสมครบ 10 ครั้งแล้ว การใช้พลังการคำนวณของ「สุขระทม」จะลดลงเป็น 1 และจำนวนดาเมจจะเพิ่มขึ้น 1 ครั้ง。"
  },
  State_71156_Desc = {
    Text = "เมื่อเริ่มต้นรอบ อกริปปาได้รับความคลั่ง 15 คะแนน。「ฝืนใจให้ทาน」ยังทำให้ อกริปปา ลดการใช้พลังการคำนวณลง 1 ในเทิร์นนี้ โดยสามารถใช้ได้สูงสุด 1 ครั้งต่อรอบ。"
  },
  State_71157_Desc = {
    Text = "เมื่อเริ่มต้นเทิร์น ซังก้าได้รับอาลีมัส 15 หน่วย。เมื่อเริ่มการต่อสู้ การ์ดคำสั่งทั้งหมดที่มีอยู่กับซังก้าจะถูกมอบให้เก็บรักษา,เตรียมพร้อม 1 และได้รับโล่ 24 คะแนน。"
  },
  State_71157_Name = {
    Text = "มิติภาพ·ซาน"
  },
  State_71158_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ดอลล์ได้รับอาลีมัส 15 หน่วย หลังจากการต่อสู้เริ่มต้นให้พลังการคำนวณของ 「การแลกเปลี่ยนที่เท่าเทียม」 ของดอลล์กลายเป็น 0 และเมื่อเล่นแล้วจะจั่วการ์ดเพิ่มอีก 2 ใบในเทิร์นถัดไป。"
  },
  State_71159_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ฟารอสจะได้รับ 15 อาลีมัส ทุกครั้งที่สร้างความเสียหายจากหนวดสัมผัส จะทำให้พิษที่ฟารอสสร้างในระหว่างการต่อสู้เพิ่มขึ้น 1% สูงสุด 100%。"
  },
  State_71160_Desc = {
    Text = "ตอนเริ่มต้นรอบ「24」จะได้รับอาลีมัส 15 หน่วย。ตอนเริ่มต้นรอบ หาก「24」อยู่ในสถานะ「บุคลิกภาพซึมเศร้า」จะได้รับอาลีมัสเพิ่มเติม 25 หน่วย，หากอยู่ในสถานะ「บุคลิกภาพคลั่ง」จะทำให้「24」อัตราการคริติคอลชั่วคราวและความเสียหายจากการโจมตีคริติคอลชั่วคราวเพิ่มขึ้น 35 %。"
  },
  State_71161_Desc = {
    Text = "เมื่อเริ่มต้นรอบ เฟนท์จะได้รับ 15 อาลีมัส ทุกครั้งที่กระตุ้นการต่อต้านความตาย จะทำให้โล่ การโต้กลับ และการตอบกลับที่เฟนท์สร้างขึ้นในการสำรวจนี้เพิ่มขึ้น 20% สูงสุด 5 ครั้ง。"
  },
  State_71162_Desc = {
    Text = "เริ่มต้นรอบโกไลแอทจะได้รับความคลั่ง 15 หน่วย หากโกไลแอทสร้างความเสียหาย 3 ครั้งใน 1 รอบ ความเสียหายที่โกไลแอทสร้างจะได้รับโบนัสพละกำลัง 1 เท่าในระหว่างการต่อสู้ครั้งนี้ คูลดาวน์ 3 รอบ。"
  },
  State_71163_Desc = {
    Text = "เริ่มต้นรอบ เฮลอต: ตรวนสีชาดจะได้รับอาลีมัส 15 คะแนน ดาเมจสกิลกดใช้ของสายเลือดเชื่อมโยง·เฮลอตเพิ่มเลือดออก 20% หากสังหารศัตรู จะทำให้ศัตรูอื่นได้รับเลือดออกเท่ากับความเสียหายที่เกิน。"
  },
  State_71164_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ออริตาได้รับความคลั่ง 15 หน่วย。「ต่อมแตกตัว」จำนวนความเสียหายเพิ่มขึ้น 1 ครั้ง หลังจากเล่น「การป้องกัน」ของออริตา จะนำการ์ด「ต่อมแตกตัว」 1 ใบใส่ในมือ。"
  },
  State_71166_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ลิลลี่จะได้รับ 15 ความคลั่ง ขีดจำกัดความอดทนของลิลลี่เพิ่มขึ้น 100% เมื่อปล่อย「บุปผานิรันดร์เหนือโคลนตม」หรือ「โจมตีเพื่อปกป้อง」 จะฟื้นฟูชีวิตเท่ากับ 8% ของสะสม「ความอดทน」。"
  },
  State_71167_Desc = {
    Text = "เมื่อเริ่มต้นรอบ โลทันจะได้รับความคลั่ง 15 หน่วย。หลังจากใช้「การป้องกัน」ของโลทันเป็นครั้งแรกในแต่ละรอบ จะวางการใช้จ่ายเพิ่มเติม 2 ใบและ「ดาบแห่งปฏิปักษ์」สุญญตาในมือ。"
  },
  State_71168_Desc = {
    Text = "เมื่อเริ่มต้นรอบ แพนเดียจะได้รับความคลั่ง 15 หน่วย เมื่อเริ่มต้นรอบจะได้รับการโต้กลับ 64 คะแนน ทุกครั้งที่มีการโต้กลับที่ไม่ใช่ชั่วคราว 4 คะแนน ความเสียหายจากการ์ดคำสั่ง「แพนเดีย」จะเพิ่มขึ้น 1 หน่วย。"
  },
  State_71169_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ชิโลจะได้รับความคลั่ง 15 คะแนน ทุกครั้งที่มีการทิ้งการ์ด 1 ใบ จะทำให้「ชิโล」ได้รับความคลั่ง 5 คะแนน。"
  },
  State_71170_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ทาวิลได้รับอาลีมัส 15 หน่วย หากในหนึ่งรอบเล่นการ์ดคำสั่งของทาวิล 6 ใบ จะวางการ์ด「กุญแจเงินอรุณรุ่ง」1 ใบในมือ (คูลดาวน์ 3 รอบ)"
  },
  State_71171_Desc = {
    Text = "เมื่อเริ่มต้นเทิร์นมิลียาห์มจะได้รับ 15 ความคลั่ง และนำการ์ด「พิธีบูชาศักดิ์สิทธิ์」1 ใบเข้าสู่มือ"
  },
  State_71172_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ดอลล์: มลายทราม จะได้รับ 15 คะแนนความคลั่ง หลังจากปล่อยระเบิดพลัง ดอลล์: มลายทราม จะทำให้ผู้ปลุกตื่นอื่นได้รับความคลั่ง 1 หน่วย ทุกครั้งที่ใช้ 20 หน่วยความคลั่ง。"
  },
  State_71173_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ซัลวาดอร์จะได้รับ 15 อาลีมัส ทุกครั้งที่สะสมเตาหลอมเลือดยังจะได้รับพละกำลัง 5% ของปริมาณสะสม. การตีและทุกข์ที่ควรถูกชำระของซัลวาดอร์จะได้รับโบนัสพละกำลัง 1 เท่าเพิ่มเติม.。"
  },
  State_71175_Desc = {
    Text = "เมื่อเริ่มต้นรอบ นอร์ดิร่าจะได้รับความคลั่ง 15 หน่วย หลังจากปลดปล่อย「ระเบิดพลัง」ของนอร์ดิรา จะได้รับการโต้กลับเท่ากับ 50% ของโล่ในขณะนั้น ใช้งานได้สูงสุด 1 ครั้งต่อรอบ。"
  },
  State_71177_Desc = {
    Text = "เมื่อเริ่มต้นเทิร์น ลิซจะได้รับ 15 อาลีมัส。「เริงระบำสู่ความตาย」การ์ดที่ทิ้งจะมีผลเพิ่มเติม 1 ครั้ง (คูลดาวน์ 3 รอบ)。"
  },
  State_71178_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ราโมน่าได้รับอาลีมัส 15 หน่วย ทุกครั้งที่เล่นการ์ดคำสั่งของราโมน่าเป็นใบที่ 3 การ์ดคำสั่งนั้นจะมีผลเพิ่มเติม 1 ครั้ง。"
  },
  State_71179_Desc = {
    Text = "เมื่อเริ่มรอบ ยูอูฮาชิได้รับความบ้าคลั่ง 15 แต้ม การใช้ความบ้าคลั่งของยูอูฮาชิลดลง 10 แต้ม ทุกครั้งที่ปลดปล่อยความบ้าคลั่งจะลดการใช้แต้มความบ้าคลั่งเพิ่มอีก 5 แต้ม รอบละสามารถปลดปล่อยความบ้าคลั่งได้ 2 ครั้ง。"
  },
  State_71180_Desc = {
    Text = "เมื่อเริ่มต้นรอบ อัลวาได้รับ 15 คะแนนอาลีมัส หากในรอบที่แล้ว อัลวาเล่นการ์ด「การป้องกัน」 2 ใบ จะวางการ์ด「ดาบแห่งญาณทัศนะ」ที่ใช้แล้ว 1 ใบในมือ; หากเล่นการ์ด「ตี」 2 ใบ จะวางการ์ด「ตั้งท่าเตรียมรบ」ที่ใช้แล้ว 1 ใบในมือ。"
  },
  State_71181_Desc = {
    Text = "เมื่อเริ่มต้นรอบ โซเรลจะได้รับความคลั่ง 15 หน่วย.ทุกครั้งที่โซเรลสร้างความเสียหาย 1 ครั้ง จะทำให้การหลอมรวมตัวอ่อน+10 สูงสุด 10 ครั้งต่อรอบ.เมื่อเกิดขึ้น 10 ครั้งแล้ว จะทำให้ดาเมจคริติคอลของโซเรลในสงครามนี้เพิ่มขึ้น 20%."
  },
  State_71182_Desc = {
    Text = "เมื่อเริ่มต้นเทิร์น ฮาเมลน์จะได้รับ 15 อาลีมัส。「เพลงโหมโรงแห่งจิตวิญญาณ」การใช้พลังการคำนวณลดลง 1 ความเสียหายพื้นฐานจำนวนครั้งเพิ่มขึ้น 1。"
  },
  State_71183_Desc = {
    Text = "เมื่อเริ่มต้นเทิร์น ทาอิสจะได้รับ 15 อาลีมัส หลังจากทาอิสเล่นการ์ดคำสั่ง 2 ใบใน 1 รอบ จะได้รับการ์ด「บุตรบริสุทธิ์」1 ใบ และพละกำลังชั่วคราว 72 คะแนน (คูลดาวน์ 3 รอบ)。"
  },
  State_71187_Desc = {
    Text = "เมื่อเริ่มต้นรอบ เซเลสเทจะได้รับ 15 อาลีมัส ก่อนจบเทิร์น หากมีการ์ดคำสั่งของเซเลสเท 1 ใบในมือ จะทำให้หนวดสัมผัส 1 ตัวโจมตีศัตรูและตอบกลับ 8 HP。"
  },
  State_71188_Desc = {
    Text = "เมื่อเริ่มต้นรอบ เมอร์ฟี่จะได้รับอาลีมัส 15 หน่วย。「ตี」และ「การป้องกัน」ของเมอร์ฟี่สามารถแปลงอาลีมัส 25% เป็นความเสียหายชั่วคราวของหนวดสัมผัส แต่จะมีผลสูงสุด 1 ครั้งต่อรอบเท่านั้น。"
  },
  State_71189_Desc = {
    Text = "เมื่อเริ่มต้นรอบ นิมเฟียได้รับอาลีมัส 15 หน่วย หลังจากเล่น「ตี」ของนิมเฟีย จะทำให้「นิมเฟีย」สร้างพิษในรอบนี้เพิ่มขึ้น 20% หลังจากเล่น「การป้องกัน」ของนิมเฟีย จะทำให้ศัตรูทั้งหมดติดพิษ 50% สูงสุดต่อรอบจะมีผล 1 ครั้งเท่านั้น。"
  },
  State_71190_Desc = {
    Text = "เมื่อเริ่มต้นรอบ โอเกียร์จะได้รับความคลั่ง 15 หน่วย ทุกครั้งที่เล่น「หอกทะลวง」หรือ「ตี」ของโอเกียร์เป็นครั้งแรกในรอบนี้ จะทำให้โล่และพละกำลังที่โอเกียร์ทำได้ในรอบนี้เพิ่มขึ้น 50%。"
  },
  State_71191_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ไรเกอร์ จะได้รับ 15 อาลีมัส ผลลัพธ์ของลูกเต๋าครั้งแรกในแต่ละรอบจะเป็น 6 เสมอ."
  },
  State_71192_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ราโมน่า: วัฏกาล จะได้รับ 15 อาลีมัส。เมื่อเกิด「ลูป」ครั้งแรกในแต่ละรอบ จะได้รับพลังงานกุญแจเงิน 500 คะแนนและ 1 ระดับ「เนเกนโทรปี」。"
  },
  State_71193_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ธูลูจะได้รับความคลั่ง 15 หน่วย การใช้ความคลั่งของธูลูลดลง 10 จุด หลังจากปลดปล่อยระเบิดพลัง จะสร้างหนวดสัมผัสชั่วคราว 2 หนวดทันที。"
  },
  State_71194_Desc = {
    Text = "เมื่อเริ่มต้นรอบ คาเรนจะได้รับความคลั่ง 15 หน่วย การเล่น「เฝ้าระวังเงียบงัน」จะคืนพลังการคำนวณที่ใช้ไปเป็นสองเท่า และมีเวลาคูลดาวน์ 3 รอบ。"
  },
  State_71271_Desc = {
    Text = "เมื่อเริ่มต้นรอบ ฮอร์ลา จะได้รับ 15 อาลีมัส。เมื่อเริ่มต้นการต่อสู้ จะได้รับอุปมาทุกอารมณ์ 1 ชั้น。「อุปมา」ผลจะเพิ่มขึ้น 50％。"
  },
  State_71272_Desc = {
    Text = "เมื่อเริ่มต้นเทิร์น เจนกินจะได้รับความคลั่ง 15 คะแนน，ดาเมจสุดท้าย +5%。ความเสียหายพื้นฐานของ「บราวน์ออกศึก」และความเสียหายที่สร้างขึ้นจะเพิ่มขึ้น 200%。"
  },
  State_71273_Desc = {
    Text = "ตอนเริ่มรอบ ดาฟโฟดิลจะได้รับความคลั่ง 15 หน่วย และ 1 ใบ 「แรงบัลดาลใจ」 ทุกครั้งที่เล่น 「กระแสคลื่นพิกล」 จะทำให้พละกำลังที่ได้รับเพิ่มขึ้น 25% ตลอดการสำรวจนี้ สูงสุด 300%。"
  },
  State_71274_Desc = {
    Text = "ตอนเริ่มรอบ ทิงค์จะได้รับความคลั่ง 15 หน่วย เมื่อการ์ดคำสั่งของทิงค์ทำให้เกิดการกระโดด จะกลับขึ้นมือ ทุกรอบจะมีผลสูงสุด 3 ครั้ง。"
  },
  State_71275_Desc = {
    Text = "เมื่อต้นเทิร์น Wanda จะได้รับ 15 ความบ้าคลั่งและสถานะ 「นำทางแห่งฝัน」 1 ชั้น หากเป็นเทิร์นมิติพิเศษ จะได้รับการ์ดชั่วคราว 「โซ่กระดูกสันหลัง」 และ 「ผู้คุ้มครองแห่งทางหลง」 เพิ่มเติมเข้าสู่มือ。"
  },
  State_71276_Desc = {
    Text = "เริ่มต้นรอบ เอริกาได้รับอาลีมัส 15 หน่วย หลังจากที่เอริกาเล่นการ์ดคำสั่ง 3 ใบใน 1 รอบ จะได้รับ 1 ใบ「แรงบัลดาลใจ」และทำให้「ระเบิดแม่เหล็กไฟฟ้า」ได้รับพละกำลังและระวังภัยเพิ่มขึ้นเป็นสองเท่า。"
  },
  State_71277_Desc = {
    Text = "เมื่อเริ่มต้นรอบ คาเซียห์จะได้รับ 15 อาลีมัส ทุกครั้งที่จั่วการ์ด 1 ใบ คาเซียห์จะได้รับ 1 หน่วยอาลีมัส เมื่อคาเซียห์ปล่อยระเบิดพลัง ศัตรูทั้งหมดจะสูญเสีย 32 พละกำลัง。"
