  State_74788_Desc = {
    Text = "\n·มีปรัชญาวิบัติ：เมื่อเริ่มสำรวจ การต่อต้านความตาย 75% จะถูกแปลงเป็นโบนัสพลังชีวิตสูงสุด โดยแปลงได้สูงสุด 300% ของการต่อต้านความตาย และเพิ่มพลังชีวิตสูงสุดได้สูงสุด 10% ทุกครั้งที่เกิดการต่อต้านความตาย จะได้รับการ์ด「กุญแจเงินประกายความหวัง」เพิ่มเติม 1 ใบในมือ.\n·แผลลึกไม่มีที่สิ้นสุด：ในการต่อสู้กับผู้นำ จำนวนการฟื้นฟูชีวิตที่ฝ่ายเรารับจะลดลง 25% ทุกครั้งที่ถึง 100% ของพลังชีวิตสูงสุด แต่จะทำให้การต่อต้านความตายรวมเพิ่มขึ้น 25% สูงสุด 3 ครั้ง.\n·เลนส์ปริซึม：เมื่อเริ่มต้นรอบ หากการโต้กลับเกิน 750% ของพลังชีวิตสูงสุด จะลดจำนวนชั้นที่เกินครึ่งหนึ่ง และการโต้กลับถาวรสามารถสะสมได้สูงสุด 2250% ของพลังชีวิตสูงสุด; หากศัตรูมีพิษเกิน 1000% ของพลังชีวิตสูงสุด จะลดจำนวนชั้นที่เกินครึ่งหนึ่ง และพิษสามารถสะสมได้สูงสุด 3000% ของพลังชีวิตสูงสุด ผู้ปลุกตื่นจะได้รับโบนัสความเสียหายจากการโต้กลับลดลง 70% แต่จะเพิ่มพิษและการโต้กลับทั้งหมดขึ้น 10% เมื่อเริ่มต้นรอบของศัตรู หากมีการตื่นรู้ทางจิตวิญญาณถูกกระตุ้น จะได้รับการโต้กลับชั่วคราว 25% ของการโต้กลับถาวรในปัจจุบัน และกระตุ้นพิษ 25% ของศัตรูทั้งหมด.\n·กรวยแสงชะตากรรม：จำนวนรอบที่มอนสเตอร์ธรรมดาปล่อย「จ้องมอง」จะกลายเป็น 6 รอบ ทุกการต่อสู้มีข้อจำกัด 15 รอบ แต่เมื่อเริ่มต้นรอบที่ 15 จะได้รับการ์ด「พรมแดนโคนแสง」1 ใบในมือ：จะเติมพลังงานกุญแจเงินและความคลั่งของผู้ปลุกตื่นทั้งหมดให้เต็มค่าสูงสุด."
  },
  State_74788_Name = {
    Text = "（ชั่วคราวไม่มีการใช้งาน）"
  },
  State_74791_Desc = {
    Text = "\n·การประสานอริธเมทิกา：เมื่อเล่นการ์ดคำสั่งครบ 10 ใบในรอบเดียว, ทุกครั้งที่เล่นการ์ดคำสั่ง 1 ใบจะได้รับ「การประสานอริธเมทิกา」1 สะสม.「การประสานอริธเมทิกา」ทำให้แต้มอริธเมทิกาในการเล่นการ์ดคำสั่งแต่ละครั้งในรอบนี้ +1, ทุกแต้มอริธเมทิกาพิเศษที่ใช้ไปจะแปลงเป็นพลังงานกุญแจเงินฟื้นฟูพลังงานกุญแจเงิน 100% ของผู้ปลุกตื่น, สามารถสะสมได้. หลังจากเปิดใช้มิติพิเศษ, รีเซ็ตผลการประสานอริธเมทิกา.\n·พลังการคำนวณเต็ม：หลังจากเล่นการ์ด จะลบผลลดแต้มอริธเมทิกาในรอบนี้ออก. เมื่ออริธเมทิกาปัจจุบันในการต่อสู้เกิน 12, จะแปลงทุกแต้มอริธเมทิกาที่เกินโดยอัตโนมัติเป็นพลังงานกุญแจเงินฟื้นฟูพลังงานกุญแจเงิน 300% ของค่าเฉลี่ยทีม.\n·ความคลั่ง：ผลเพิ่มเปอร์เซ็นต์อาลีมัสลดลงครึ่งหนึ่ง. หลังจากผู้ปลุกตื่นแต่ละคนปล่อยระเบิดพลัง, อาลีมัสพื้นฐานของเขาจะ +10. เมื่อสิ้นสุดรอบ ทุก 1 ผู้ปลุกตื่นที่ไม่ได้ปล่อยระเบิดพลัง จะได้รับพลังงานกุญแจเงินฟื้นฟูพลังงานกุญแจเงิน 200％ ของค่าเฉลี่ยทีม."
  },
