  },
  State_74932_Desc = {
    Text = "เมื่อเล่นการ์ด「ตี」,การ์ด「การป้องกัน」และการ์ด「ทักษะ」จะอัปเกรดผลที่เกี่ยวข้องใน「การค้าต้องห้าม」。"
