  },
  State_74947_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อเริ่มต้นรอบ จะเพิ่ม [StateArg1] ชั้นล็อคการกระทำให้ศัตรูที่มี<HPAndShieldMin:HP และโล่ต่ำที่สุด>. หลังจากผู้สวมใส่สังหารเป้าหมาย จะทริกเกอร์ผลนี้ทันทีอีกครั้ง."
  },
  State_74947_Name = {
    Text = "หมวกแม่มดขอบกว้าง"
  },
  State_74948_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：หลังจาก「ระเบิดพลัง」ทำให้ศัตรูที่มีความคลั่งสูงสุดสูญเสีย [StateArg1] ความคลั่งและได้รับ<PVPEmptinessKeywords:ความว่างเปล่า>."
  },
  State_74948_Name = {
    Text = "ลูกตุ้มสะกดจิต"
  },
  State_76236_Desc = {
    Text = "\n·การตื่นรู้ด้วยกุญแจเงิน: เมื่อพลังงานกุญแจเงินเต็ม สามารถเลือก「การตื่นรู้ด้วยกุญแจเงิน」เพิ่มเติมเพื่อนำการ์ดวิญญาณตื่นรู้ของร่างตื่นที่ระบุใส่ในมือและทำให้ได้รับ「เก็บรักษา」มีผลตลอดการต่อสู้นี้.「การตื่นรู้ด้วยกุญแจเงิน」สามารถเปิดใช้งานได้เพียง 1 ครั้งต่อรอบ และคูลดาวน์แยกจาก「คำสั่งกุญแจ」.\n·พลังงานกุญแจเงินโอเวอร์โหลด: เมื่อใช้「การตื่นรู้ด้วยกุญแจเงิน」ทุกๆ ร่างตื่นที่ปลดล็อควิญญาณตื่นรู้แล้ว 1 ตัว จะหักพลังงานกุญแจเงินเพิ่มเติม 1000 จุด ผลนี้อาจทำให้พลังงานกุญแจเงินติดลบได้.\n·การแกะสลักไฟล์: ทุกๆ 1 คำสั่งกุญแจที่ผู้พิทักษ์มี จะเพิ่มความลึกของการศึกษาเกี่ยวกับวัตถุและความรู้ทางจิตวิญญาณเชิงลึก 1％ สูงสุด 50％. ผลของวงล้อมชีวิต R ทั้งหมดเปลี่ยนเป็นเพิ่มโอกาสที่เรลิกภาพมิติของผู้สวมใส่จะปรากฏขึ้น 100%."
  },
  State_76236_Name = {
    Text = "ความสว่างระยิบระยับของเงิน"
  },
  State_76277_Desc = {
    Text = "ทีมเดียว：เมื่อเริ่มต้นการต่อสู้กับผู้นำ จะใช้รอยดำสูงสุด 50 รอย ทุกการใช้ 1 รอยดำจะได้รับ <WeaponEffect_Num:[StateArg1]%> <DeathResistanceIconKeywords: การต่อต้านความตาย>。ในบทของดวงดาว ผลจะเปลี่ยนเป็น「เพิ่มโอกาสในการปรากฏของเรลิกภาพมิติที่ผู้สวมใส่มีขึ้น 100%」。"
  },
  State_76277_WeaponDesc = {
    Text = "หลังจากเริ่มการต่อสู้กับผู้นำ จะใช้รอยดำสูงสุด 50 รอย โดยการใช้รอยดำ 1 รอย จะได้รับ <WeaponEffect_Num:[StateArg1]%> <DeathResistanceIconKeywords: การต่อต้านความตาย> ในบทของดวงดาว ผลจะเปลี่ยนเป็น「เพิ่มโอกาสในการปรากฏของเรลิกมิติของผู้สวมใส่ 100%」。"
  },
  State_76278_Desc = {
    Text = "ทีมเดียว: ทุกครั้งที่เดินผ่านช่องใหม่ จะฟื้นฟู <WeaponEffect_Num:[StateArg1]%> ของเลือดที่สูญเสียไป หลังจากใช้ร่างกายจิตวิญญาณฉุกเฉิน อัตราคริติคอลและดาเมจคริติคอลของผู้ปลุกตื่นทั้งหมดจะเพิ่มขึ้น 100% ในบทของดวงดาว ผลจะเปลี่ยนเป็น「เพิ่มโอกาสในการปรากฏตัวของเรลิกภาพมิติที่ผู้สวมใส่มี」100%。"
  },
  State_76278_WeaponDesc = {
    Text = "ทุกครั้งที่เดินผ่านช่องใหม่ จะฟื้นฟู [StateArg1]% ของเลือดที่สูญเสียไป ([DescArg1]) หลังจากใช้ร่างกายจิตวิญญาณฉุกเฉิน อัตราคริติคอลและดาเมจคริติคอลของผู้ปลุกตื่นทั้งหมดจะเพิ่มขึ้น 100% ในบทของดวงดาว ผลจะเปลี่ยนเป็น「เพิ่มโอกาสในการปรากฏตัวของเรลิกภาพมิติของผู้สวมใส่ขึ้น 100%」。"
  },
  State_76279_Desc = {
    Text = "ทีมเดียว：ราคาของผู้ปลุกตื่นในรอยละลายลดลง <WeaponEffect_Num:[StateArg1]> จุดรอยดำ ผู้สวมใส่จะได้รับความรู้ทางจิตวิญญาณติดตัว ในบทของดวงดาว ผลจะเปลี่ยนเป็น「เพิ่มโอกาสในการปรากฏของเรลิกภาพมิติของผู้สวมใส่ขึ้น 100％」。"
  },
  State_76279_WeaponDesc = {
    Text = "ราคาของผู้ปลุกตื่นที่ตื่นรู้ในรอยละลายลดลง <WeaponEffect_Num:[StateArg1]> รอยดำ ผู้สวมใส่จะได้รับความรู้ทางจิตวิญญาณที่ติดตัว ในบทของดวงดาว ผลจะเปลี่ยนเป็น「เพิ่มโอกาสในการปรากฏของสิ่งสร้างภาพมิติที่ผู้สวมใส่มีขึ้น 100%」。"
  },
  State_76280_Desc = {
    Text = "ทีมเดียว: ปริมาณการฟื้นฟูที่พื้นที่พักผ่อนเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> เมื่อเลือกฟื้นฟูเลือด จะเพิ่มการ์ด「แรงบัลดาลใจ」2 ใบเข้าสู่สำรับไพ่ ในบทของดวงดาว ผลจะเปลี่ยนเป็น「เพิ่มโอกาสในการปรากฏตัวของเรลิกภาพมิติของผู้สวมใส่ขึ้น 100%」。"
