    Text = "เมื่อจบเทิร์น จะอัญเชิญมอนสเตอร์การย่อยสลาย 2 ตัว โดยมีจำนวนสูงสุดที่สามารถมีอยู่พร้อมกันได้ 2 ตัว เมื่อมอนสเตอร์การย่อยสลายที่อัญเชิญตายลงไป 「การหลอมละลาย·ดอร์」จะสูญเสีย 5% ของ Max HP。"
  },
  State_77692_Name = {
    Text = "ประตูเหว"
  },
  State_77693_Desc = {
    Text = "หลังจากเสียชีวิต 「ดอร์·เมลต์」 จะสูญเสีย 5% ของพลังชีวิตสูงสุด。"
  },
  State_77693_Name = {
    Text = "การหลอมละลาย"
  },
  State_78102_Desc = {
    Text = "ลดความเสียหายที่ทำได้ 15% และเพิ่มความเสียหายที่ได้รับ 30% จนกว่าการต่อสู้จะสิ้นสุดลง。"
  },
  State_78102_Name = {
    Text = "การพิการจากการโอเวอร์คล็อก"
  },
  State_78694_Desc = {
    Text = "เมื่อการต่อสู้เริ่มต้น จะได้รับ [Arg1] คะแนนพละกำลัง ในแต่ละรอบที่เริ่มต้น จะได้รับพละกำลังชั่วคราว [Arg3] หน่วย สำหรับทุก [Arg2] คะแนนพละกำลังถาวร สูงสุดจะได้รับพละกำลังชั่วคราว [Arg4] หน่วย และจะสูญเสียโล่ครึ่งหนึ่งที่ได้รับจากพละกำลังชั่วคราวที่ได้จากเรลิกเมื่อจบเทิร์น。"
  },
  State_78696_Desc = {
    Text = "หลังจากการตื่นรู้ด้วยกุญแจเงิน เลือกผู้ปลุกตื่นที่ตรงกัน [Arg1] ใบ「ทักษะ」เพื่อนำไปใช้ และนำสำเนาที่ใช้ไป [Arg2] ใบใส่กองไพ่ที่สุ่ม。"
  },
  State_78697_Desc = {
    Text = "ในระยะเริ่มต้นถูกเพิ่ม [Arg2] ชั้นพิษ ในอัลตร้าสเปซ ทุกครั้งที่มีที่ว่าง 1 ตำแหน่งจะได้รับ [Arg1] คะแนนพลัง"
  },
  State_78698_Desc = {
    Text = "ขีดจำกัดอริธเมทิกา -[Arg1]。เมื่อเล่นการ์ดที่มีแต้มอริธเมทิกามากกว่าหรือเท่ากับ [Arg2] จะได้รับอริธเมทิกา 1 หน่วย แต่ละรอบทริกเกอร์ได้สูงสุด [Arg3] ครั้ง。"
  },
  State_78699_Desc = {
    Text = "จั่วไพ่เพิ่ม [Arg1] ใบหลังจากจั่ว แต่เลือกทิ้ง [Arg2] ใบในมือ。"
  },
  State_78700_Desc = {
    Text = "ความเสียหายพื้นฐานที่เกิดจากผู้ปลุกตื่นทั้งหมดเพิ่มขึ้น [Arg1]%，ทุกครั้งที่รีเซ็ตสำรับจะเพิ่มขึ้นอีก [Arg2]%，แต่จะมีการเพิ่มการ์ด「โซเซ」1 ใบเข้าไปในมือ โดยค่าที่เพิ่มขึ้นสูงสุดคือ [Arg3]%。"
  },
  State_78701_Desc = {
    Text = "เมื่อเริ่มต้นรอบ หากมีหนวดสัมผัสถาวรมากกว่า [Arg1] เส้น จะสูญเสียหนวดสัมผัส [Arg2] เส้นและได้รับหนวดสัมผัสชั่วคราว [Arg3] เส้น มิฉะนั้น จะได้รับหนวดสัมผัสชั่วคราว [Arg4] เส้น。"
  },
  State_78702_Desc = {
    Text = "หลังจากการตื่นรู้ด้วยกุญแจเงิน จะใช้พลังงานกุญแจเงินเพิ่มเติมจำนวน [Arg1] คะแนน ทำให้การใช้พลังการคำนวณของการ์ดวิญญาณตื่นรู้ที่ได้รับกลายเป็น 0 หลังจากเล่นจะทำให้ผู้ปลุกตื่นที่เกี่ยวข้องได้รับความคลั่งเพิ่มเติมจำนวน [Arg2] คะแนน。"
  },
  State_78703_Desc = {
    Text = "เมื่อเริ่มการต่อสู้ ทำให้ศัตรูทั้งหมดได้รับพิษ [Arg1] หน่วย ในช่วงก่อนเริ่มต้นรอบ จะลบพิษ [Arg2]% ของศัตรู และทำให้เกิดเลือดออก [Arg3]% ของปริมาณที่ถูกลบออก。"
  },
  State_78710_Desc = {
    Text = "ทุกครั้งที่เล่นการ์ดคำสั่ง จะทำให้ผู้ปลุกตื่นที่เกี่ยวข้องสร้างความเสียหายสุดท้ายเพิ่มขึ้น [Arg1] % ในรอบนั้น แต่จะทำให้สูญเสียความคลั่ง [Arg2] จุด โดยจะสามารถเกิดขึ้นได้สูงสุด [Arg3] ครั้งในแต่ละรอบ。"
  },
  State_78712_Desc = {
    Text = "เมื่อเริ่มรอบ ความเข้มข้นของการหลอมรวมของตัวอ่อน+ [Arg1] ตัวอ่อนของคุณจะถูกทิ้งเมื่อสิ้นสุดรอบ."
  },
  State_78713_Desc = {
    Text = "เมื่อเริ่มต้นรอบ จะได้รับ [Arg1] คะแนนการโต้กลับ หลังจากปล่อยคลั่งไคล้ถึงขีดสุด [Arg2] ครั้งในหนึ่งรอบ จะลบการโต้กลับถาวร [Arg3]% ของตนเอง และได้รับการโต้กลับชั่วคราวในปริมาณ [Arg4]% ที่ถูกลบไป โดยมีเวลาคูลดาวน์ [Arg5] รอบ。"
  },
  State_78781_Desc = {
    Text = "ลดพลังของเป้าหมายชั่วคราว, และได้รับพลังชั่วคราวเท่ากัน."
  },
