  State_84257_Desc = {
    Text = "ทีมเดียว: ผู้สวมใส่ระเบิดพลังทำให้โล่เพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> หลังจากปลดปล่อยระเบิดพลัง ร่างกายที่ตื่นขึ้นทุกคนจะเพิ่มความเสียหายจากการโจมตีคริติคอลชั่วคราว <WeaponEffect_Num:[StateArg2]%> และทุกหนวดสัมผัสจะเพิ่มขึ้น 1% สำหรับทุกตัว ทุกครั้งที่สำรวจจะกระตุ้นการต่อต้านความตายเป็นครั้งแรก จะฟื้นฟู HP สูงสุด <WeaponEffect_Num:[StateArg3]%> ในรอบถัดไป"
  },
  State_84257_WeaponDesc = {
    Text = "โล่ที่เพิ่มขึ้นจากการระเบิดพลังของผู้สวมใส่เพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> หลังจากปล่อยระเบิดพลัง ร่างที่ถูกปลุกทุกตัวจะเพิ่มความเสียหายจากการโจมตีคริติคอลชั่วคราว <WeaponEffect_Num:[StateArg2]%> โดยแต่ละหนวดสัมผัสจะเพิ่มขึ้น 1%。ทุกครั้งที่เกิดการต่อต้านความตายเป็นครั้งแรกในการสำรวจ รอบถัดไปจะเริ่มต้นด้วยการตอบกลับ <WeaponEffect_Num:[StateArg3]%> ของพลังชีวิตสูงสุด。"
  },
  State_84272_Desc = {
