  State_89422_Desc = {
    Text = "ความอาลีมัสที่เกิดจากผู้ปลุกเสกทั้งหมดเพิ่มขึ้น 100% สามารถปลดปล่อยความยกย่องได้ 2 ครั้งในแต่ละรอบ。"
