  State_89447_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：ขีดจำกัดไพ่บนมือ + [Arg3]. หลัง「ระเบิดพลัง」แต้มอริธเมทิกาพื้นฐานของ「ทักษะ」ในมือที่มีแต้มอริธเมทิกาเป็น [Arg1] จะลดลง [Arg2]."
  },
  State_89447_Name = {
    Text = "อิสรภาพอันหนักอึ้ง"
  },
  State_89448_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อชะตา>：เมื่อสิ้นสุดเทิร์น มอบการ์ด<PVPDerivativeCardKeywords_16:「ขนนกดำ」> [StateArg1] ใบให้ฝ่ายเดียวกันที่มีพลังชีวิตและเกราะต่ำที่สุด"
