  State_89448_Name = {
    Text = "ขนนกที่โดดเดี่ยว"
  },
  State_89554_Name = {
    Text = "กรวยแสงชะตากรรม"
  },
  State_89555_Desc = {
    Text = "ทีมเดียว: หลังจากผู้สวมใส่ปล่อยระเบิดพลัง, ทำให้ความเสียหายพื้นฐานของระเบิดพลังเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>, โล่และการฟื้นฟู HP เพิ่มขึ้น <WeaponEffect_Num:[StateArg2]%>, สะสมได้สูงสุด 5 ครั้ง. อัตราการประสานที่ผู้สวมใส่ได้รับจากการสำรวจเพิ่มขึ้น <WeaponEffect_Num:[StateArg3]%>."
  },
  State_89555_WeaponDesc = {
    Text = "หลังจากผู้สวมใส่ปลดปล่อยระเบิดพลัง ความเสียหายพื้นฐานจากระเบิดพลังจะเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> การตอบกลับโล่และชีวิตจะเพิ่มขึ้น <WeaponEffect_Num:[StateArg2]%> สูงสุดสะสมได้ 5 ครั้ง หลังจากสำเร็จการสำรวจ อัตราการประสานที่ผู้สวมใส่ได้รับจะเพิ่มขึ้น <WeaponEffect_Num:[StateArg3]%>。"
  },
  State_89557_Name = {
    Text = "เลนส์ปริซึม"
  },
  State_89559_Desc = {
    Text = "\n·มีปรัชญาวิบัติ: เมื่อเริ่มต้นการสำรวจ 75％ ของการต่อต้านความตายจะถูกแปลงเป็นโบนัส Max HP สูงสุดแปลงได้ 300％ ของการต่อต้านความตาย และเพิ่ม Max HP ได้สูงสุด 10％. ทุกครั้งที่เปิดใช้งานการต่อต้านความตาย จะนำการ์ด「กุญแจเงินประกายความหวัง」1 ใบใส่ในมือเพิ่มเติม.\n·แผลลึกไม่มีที่สิ้นสุด: ในการต่อสู้กับผู้นำ ทุกครั้งที่ปริมาณ HP ที่ฝ่ายเราได้รับถึง 100% ของขีดจำกัด HP จะลดผลการฟื้นฟู HP ที่ได้รับต่อไป 25% แต่เพิ่มปริมาณการต่อต้านความตายปัจจุบันทั้งหมด 25% เปิดใช้งานได้สูงสุด 3 ครั้ง.\n·เลนส์ปริซึม: เมื่อเริ่มต้นรอบ หากเคาน์เตอร์เกิน 2000％ ของขีดจำกัด HP จะลดสะสมส่วนที่เกินลงครึ่งหนึ่ง และเคาน์เตอร์ถาวรสะสมได้สูงสุด 6000％ ของขีดจำกัด HP; หากศัตรูมีพิษเกิน 3000％ ของขีดจำกัด HP จะลดสะสมส่วนที่เกินลงครึ่งหนึ่ง และพิษสะสมได้สูงสุด 9000％ ของขีดจำกัด HP. โบนัสความเสียหายที่ร่างตื่นได้รับจากเคาน์เตอร์ลดลง 70% แต่พิษและเคาน์เตอร์ทั้งหมดที่ก่อให้เกิดเพิ่มขึ้น 10%. ทุกครั้งที่ตื่นรู้ร่างตื่น 1 ตัว: หลังสิ้นสุดรอบจะได้รับเคาน์เตอร์ชั่วคราว 25% ของเคาน์เตอร์ถาวรปัจจุบัน และเมื่อสิ้นสุดรอบของฝ่ายศัตรูจะเปิดใช้งานพิษ 25% ของศัตรูทั้งหมดเพิ่มเติม.\n·กรวยแสงชะตากรรม: จำนวนรอบที่มอนสเตอร์ธรรมดาปล่อย「จ้องมอง」เปลี่ยนเป็น 6 รอบ. เมื่อเริ่มต้นรอบที่ 15 จะนำการ์ด「พรมแดนโคนแสง」1 ใบใส่ในมือ: เติมพลังงานกุญแจเงินและอาลีมัสของร่างตื่นทั้งหมดให้เต็มสูงสุด."
  },
  State_89559_Name = {
    Text = "การบิดเบือนกาลเวลา"
  },
  State_89567_Desc = {
    Text = "การ์ดใบนี้ใช้พลังการคำนวณ -[StateArg1]。"
  },
  State_89567_Name = {
    Text = "เกิดใหม่ในดินแดนที่สูญเสีย"
  },
  State_89568_Desc = {
    Text = "<PVPWeaponKeywords:วงล้อมชีวิต>：เมื่อผู้สวมใส่เสียชีวิต จะนำ「ทักษะ」ที่ใช้แต้มอริธเมทิกาของตน -[StateArg1] ใบใส่เข้าไปในกองไพ่ที่สุ่ม และเปลี่ยนผู้เป็นเจ้าของเป็นพันธมิตรที่มีชีวิตที่เหลือสูงสุด。"
  },
  State_89568_Name = {
    Text = "เกิดใหม่ในดินแดนที่สูญเสีย"
  },
  State_89571_Name = {
    Text = "「 โรงละครกำลังไหม้ 」"
  },
  State_89572_Desc = {
    Text = "เมื่อเริ่มต้นรอบ จะมีการเพิ่มสถานะ<BurningKeywords:เผาไหม้>ให้กับการ์ดแบบสุ่ม [DescArg1] ใบในสำรับไพ่ และได้รับพละกำลังชั่วคราว [DescArg2] คะแนน ทุกๆ 2 รอบ จำนวนการ์ดที่เพิ่มสถานะเผาไหม้จะเพิ่มขึ้น 1 และพละกำลังชั่วคราวที่ได้รับจะเพิ่มขึ้น [DescArg3] คะแนน。"
  },
  State_89572_Name = {
    Text = "「 โรงละครกำลังไหม้ 」"
  },
  State_89626_Desc = {
    Text = "หลังจากการตื่นรู้ด้วยกุญแจเงิน จะนำการ์ด「กุญแจเงินประกายความหวัง」 1 ใบใส่ในมือ เมื่อผู้ปลุกตื่นทั้งหมดตื่นแล้ว ในตอนเริ่มต้นแต่ละเทิร์นจะค้นพบผู้สนับสนุนการปลุกตื่นแบบสุ่ม 1 คน。"
  },
  State_89631_Desc = {
    Text = "กระโดดสองชั้นเพิ่มเติม [Layer] ครั้ง"
  },
  State_89634_Desc = {
    Text = "การปลุกเร้าความรู้ทางจิตวิญญาณ 4"
  },
  State_89634_Name = {
    Text = "การปลุกเร้าความรู้ทางจิตวิญญาณ 4"
  },
  State_89637_Desc = {
    Text = "การ์ดคำสั่งใบแรกในแต่ละเทิร์นจะมีผลเพิ่มเติม 1 ครั้ง เมื่อทำลายล้างจะสร้างหนวดสัมผัส 1 เส้น หลังจากเปลี่ยนหนวดสัมผัสเป็นท่าทาง「คลื่นกระหน่ำ」 ผลของการวาร์ปการ์ดคำสั่ง 2 ใบในรอบนี้จะถูกกระตุ้นแน่นอนและเข้าสู่มิติพิเศษ คูลดาวน์ 3 รอบ。"
  },
  State_89640_Desc = {
    Text = "ความชำนาญดินแดนเพิ่มขึ้น 200 คะแนน เมื่อใช้เตาหลอมเลือด ความเสียหายจากหนวดสัมผัสจะเพิ่มขึ้น 15% ทุกครั้งที่โจมตีหนวดสัมผัส จะสะสม [Arg3] คะแนนเตาหลอมเลือด。"
  },
  State_89642_Desc = {
    Text = "ขีดจำกัดไพ่บนมือ +2 หลังจากปล่อยคลั่งไคล้ถึงขีดสุด ความเสียหายสุดท้ายชั่วคราวเพิ่มขึ้น 10% เมื่อการ์ดเข้าสู่มิติพิเศษ ตัวอ่อน 1 ใบในมือจะเปลี่ยนเป็นบุตรบริสุทธิ์ ทุกครั้งที่สร้างตัวอ่อน 1 หน่วย การใช้พลังการคำนวณของการ์ดแบบสุ่มในมิติพิเศษจะลดลง 1.。"
  },
  State_89669_Desc = {
    Text = "ปลุกกุญแจเงิน 4"
  },
  State_89669_Name = {
    Text = "ปลุกกุญแจเงิน 4"
  },
  State_89759_Desc = {
    Text = "หลังจากปลดปล่อยกลุ่มแชท ราโมนาจะได้รับอัตราโจมตีสำคัญชั่วคราว 50％"
  },
  State_89759_Name = {
    Text = "ความผูกพันที่มีค่า"
  },
  State_90023_Name = {
    Text = "สถานะที่ใช้สำหรับการตั้งค่าตารางคงที่ ในตอนนี้ถูกละทิ้งไป."
  },
  State_90059_Desc = {
    Text = "เมื่อได้รับความเสียหายจากการโจมตีหรือหนวดสัมผัสในรอบนี้ จะลบการกัดกร่อนในปริมาณเท่ากันและสูญเสีย HP [DescArg1]％ ของปริมาณที่ลบออก เมื่อได้รับความเสียหายอื่นจะลบการกัดกร่อน 50% ของปริมาณความเสียหาย."
  },
  State_90059_Name = {
    Text = "กัดกร่อน"
  },
  State_90094_Name = {
    Text = "ขนนกสีนิล"
  },
  State_90218_Desc = {
    Text = "ทีมเดียว: ขีดจำกัดไพ่บนมือ+2, ผลเดียวกันไม่สามารถสะสมได้. ผู้สวมใส่สร้างโล่และความเสียหายพื้นฐานเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%>, หลังจากเข้าสู่เทิร์นอัลตร้าได้รับ <WeaponEffect_Num:[StateArg2]> หน่วยอาลีมัส. หลังจากปล่อย「ทำลายล้าง」ความเสียหายจากการโจมตีคริติคอลชั่วคราวของทุกผู้ปลุกตื่นเพิ่มขึ้น +<WeaponEffect_Num:[StateArg3]%>, คูลดาวน์ 3 รอบ.。"
  },
  State_90218_WeaponDesc = {
    Text = "ขีดจำกัดไพ่บนมือ +2 ผลลัพธ์ชนิดเดียวกันไม่สามารถซ้อนทับกันได้ ผู้สวมใส่สร้างโล่และความเสียหายพื้นฐานเพิ่มขึ้น <WeaponEffect_Num:[StateArg1]%> เมื่อเข้าสู่เทิร์นอัลตร้า จะได้รับอาลีมัส <WeaponEffect_Num:[StateArg2]> หน่วย หลังจากปล่อย「ทำลายล้าง」ความเสียหายจากการโจมตีคริติคอลชั่วคราวของผู้ปลุกตื่นทั้งหมดเพิ่มขึ้น +<WeaponEffect_Num:[StateArg3]%> และมีเวลาคูลดาวน์ 3 รอบ。"
  },
  State_90221_Desc = {
